// ── calculadoras completas da usuária (artefatos próprios), embutidas como iframe; revisão 10/10/2026
const EMB_HTML = {};
EMB_HTML["vitd_full"] = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Reposição de vitamina D — calculadora clínica SUS</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{\n  --bordo:#5C1A2B;\n  --bordo-deep:#3B0F1A;\n  --bone:#F7F4EF;\n  --paper:#FFFDFA;\n  --ink:#1C1A19;\n  --slate:#585048;\n  --rule:#DDD4C7;\n  --teal:#1F5C58;\n  --brass:#9A6B12;\n  --crimson:#A3182B;\n  --ok:#1F5C58;\n  --surface2:#F2ECE3;\n  --hover:#F4EEE4;\n  --sel:#F6ECEE;\n  --track:#E7DFD3;\n  --rxbg:#FBF7F0;\n  --field:#FFFFFF;\n  --navy:#2E4A7D;\n  --onbordo:#F0DDE0;\n  --onbordo-dim:#DBB7BE;\n  --onbordo-strong:#FFFFFF;\n  --headfg:#E3D3D6;\n  --headeyebrow:#C9A9AF;\n  --stopbg:#FBEDEE; --stopbd:#E0B6BC; --stopfg:#6E1220;\n  --warnbg:#FBF3E2; --warnbd:#E2CE9E; --warnfg:#5F420A;\n  --infobg:#EAF1F0; --infobd:#AFC9C6; --infofg:#123C39;\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:env(safe-area-inset-bottom,0px);\n}\n\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n    --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n    --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n    --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n    --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n    --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n    --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n    --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n    --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n    --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n  --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n  --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n  --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n  --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n  --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n  --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n  --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n  --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n  --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\n.tw{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:0 0 10px}\n.tw table{margin:0;min-width:100%}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  background:var(--bone);\n  color:var(--ink);\n  font-family:\"Public Sans\",system-ui,sans-serif;\n  font-size:15px;\n  line-height:1.5;\n  -webkit-font-smoothing:antialiased;\n}\n.wrap{max-width:860px;margin:0 auto;padding:0 16px 80px}\n\n/* ---------- header ---------- */\nheader{\n  background:var(--bordo-deep);\n  color:var(--bone);\n  padding:26px 0 22px;\n  margin-bottom:22px;\n  border-bottom:4px solid var(--bordo);\n}\nheader .wrap{padding-bottom:0}\n.eyebrow{\n  font-family:\"IBM Plex Mono\",monospace;\n  font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;\n  color:var(--headeyebrow);margin:0 0 8px;\n}\nh1{\n  font-family:\"Fraunces\",serif;\n  font-weight:600;font-size:clamp(26px,6vw,38px);\n  line-height:1.05;margin:0 0 10px;letter-spacing:-.01em;\n}\n.sub{margin:0;font-size:13.5px;color:var(--headfg);max-width:62ch}\n.sub b{color:var(--onbordo-strong);font-weight:600}\n\n/* ---------- sections ---------- */\nsection{\n  background:var(--paper);\n  border:1px solid var(--rule);\n  border-radius:3px;\n  margin-bottom:14px;\n  overflow:hidden;\n}\n.shead{\n  display:flex;align-items:baseline;gap:10px;\n  padding:11px 14px;border-bottom:1px solid var(--rule);\n  background:var(--surface2);\n}\n.snum{\n  font-family:\"IBM Plex Mono\",monospace;font-size:11px;font-weight:600;\n  color:var(--bordo);letter-spacing:.08em;\n}\n.stitle{font-family:\"Fraunces\",serif;font-weight:600;font-size:17px;letter-spacing:-.01em}\n.sbody{padding:14px}\n\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:10px 12px}\nlabel{display:block}\n.lab{\n  display:block;font-size:11px;font-weight:600;letter-spacing:.04em;\n  text-transform:uppercase;color:var(--slate);margin-bottom:3px;\n}\n.unit{font-weight:400;text-transform:none;letter-spacing:0;color:#8B8177}\ninput[type=number],input[type=text],select{\n  width:100%;padding:8px 9px;border:1px solid var(--rule);border-radius:2px;\n  background:var(--field);color:var(--ink);\n  font-family:\"IBM Plex Mono\",monospace;font-size:15px;\n}\ninput:focus,select:focus{outline:2px solid var(--bordo);outline-offset:0;border-color:var(--bordo)}\nselect{font-family:\"Public Sans\",sans-serif}\n\n.checks{display:grid;grid-template-columns:1fr;gap:2px}\n@media(min-width:640px){.checks{grid-template-columns:1fr 1fr;gap:2px 16px}}\n.chk{display:flex;gap:8px;align-items:flex-start;padding:5px 4px;border-radius:2px;cursor:pointer;font-size:13.5px;line-height:1.35}\n.chk:hover{background:var(--hover)}\n.chk input{margin:2px 0 0;accent-color:var(--bordo);width:16px;height:16px;flex:0 0 auto}\n.grouplab{\n  font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.12em;\n  text-transform:uppercase;color:var(--bordo);margin:14px 0 6px;\n  padding-bottom:4px;border-bottom:1px dotted var(--rule);\n}\n.grouplab:first-child{margin-top:0}\n\n.radios{display:flex;flex-wrap:wrap;gap:8px}\n.radios label{\n  border:1px solid var(--rule);border-radius:2px;padding:7px 11px;cursor:pointer;\n  font-size:13px;background:var(--field);display:flex;gap:7px;align-items:center;\n}\n.radios input{accent-color:var(--bordo)}\n.radios label:has(input:checked){border-color:var(--bordo);background:var(--sel);font-weight:600}\n\n/* ---------- result ---------- */\n#out{margin-top:26px}\n.verdict{\n  background:var(--bordo);color:#fff;border-radius:3px;padding:16px 16px 14px;margin-bottom:12px;\n}\n.verdict .vlab{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--onbordo-dim);margin-bottom:5px}\n.verdict h2{font-family:\"Fraunces\",serif;font-weight:600;font-size:23px;margin:0 0 6px;line-height:1.12}\n.verdict p{margin:0;font-size:13.5px;color:var(--onbordo)}\n.cid{\n  display:inline-block;margin-top:9px;font-family:\"IBM Plex Mono\",monospace;font-size:12px;\n  background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);\n  padding:3px 8px;border-radius:2px;\n}\n\n/* signature: staging ruler */\n.ruler{margin:0 0 14px;background:var(--paper);border:1px solid var(--rule);border-radius:3px;padding:14px}\n.ruler h3{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--bordo);margin:0 0 12px;font-weight:600}\n.track{display:flex;gap:3px;margin-bottom:8px}\n.seg{flex:1;position:relative}\n.segbar{height:9px;background:var(--track);border-radius:1px}\n.seg.on .segbar{background:var(--bordo)}\n.seg.here .segbar{background:var(--bordo);box-shadow:0 0 0 2px var(--paper),0 0 0 4px var(--bordo)}\n.segtxt{font-size:10.5px;line-height:1.25;color:var(--slate);margin-top:7px;padding-right:6px}\n.seg.here .segtxt{color:var(--bordo);font-weight:700}\n.rulernote{font-size:12px;color:var(--slate);margin:10px 0 0;padding-top:9px;border-top:1px dotted var(--rule)}\n\n.card{background:var(--paper);border:1px solid var(--rule);border-radius:3px;margin-bottom:12px}\n.card h3{\n  margin:0;padding:10px 14px;border-bottom:1px solid var(--rule);background:var(--surface2);\n  font-family:\"Fraunces\",serif;font-weight:600;font-size:16px;\n}\n.card .inner{padding:13px 14px}\n.card p{margin:0 0 9px}\n.card p:last-child{margin-bottom:0}\n.card ul{margin:0 0 9px;padding-left:19px}\n.card li{margin-bottom:5px}\n\n.route{border-left:4px solid var(--teal)}\n.route h3{color:var(--teal)}\n.route.oral{border-left-color:var(--bordo)}\n.route.oral h3{color:var(--bordo)}\n\n.rx{\n  font-family:\"IBM Plex Mono\",monospace;font-size:12.5px;line-height:1.65;\n  white-space:pre-wrap;background:var(--rxbg);border:1px solid var(--rule);\n  padding:12px;border-radius:2px;margin:0;overflow-x:auto;\n}\n.btn{\n  font-family:\"Public Sans\",sans-serif;font-size:13px;font-weight:600;\n  background:var(--bordo);color:#fff;border:0;border-radius:2px;\n  padding:9px 15px;cursor:pointer;margin-top:10px;\n}\n.btn:hover{background:var(--bordo-deep)}\n.btn:focus-visible{outline:2px solid var(--ink);outline-offset:2px}\n\n.flag{\n  display:flex;gap:9px;padding:10px 12px;border-radius:2px;margin-bottom:8px;font-size:13.5px;line-height:1.4;\n  border:1px solid;\n}\n.flag b{display:block;margin-bottom:2px}\n.flag.stop{background:var(--stopbg);border-color:var(--stopbd);color:var(--stopfg)}\n.flag.warn{background:var(--warnbg);border-color:var(--warnbd);color:var(--warnfg)}\n.flag.info{background:var(--infobg);border-color:var(--infobd);color:var(--infofg)}\n.flag .ic{font-family:\"IBM Plex Mono\",monospace;font-weight:600;flex:0 0 auto}\n\ntable{width:100%;border-collapse:collapse;font-size:13px;margin:0 0 10px}\nth,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--rule);vertical-align:top}\nth{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);font-weight:600}\ntd.num{font-family:\"IBM Plex Mono\",monospace}\n.tagok{color:var(--ok);font-weight:600}\n.tagbad{color:var(--crimson);font-weight:600}\n.tagmid{color:var(--brass);font-weight:600}\n\n.empty{\n  text-align:center;padding:34px 18px;color:var(--slate);\n  border:1px dashed var(--rule);border-radius:3px;background:var(--paper);\n}\n.empty b{display:block;font-family:\"Fraunces\",serif;font-size:18px;color:var(--ink);margin-bottom:5px;font-weight:600}\n\nfooter{margin-top:30px;padding-top:16px;border-top:1px solid var(--rule);font-size:11.5px;color:var(--slate);line-height:1.55}\nfooter b{color:var(--ink)}\n\n@media print{\n  body{background:#fff}\n  header{background:#fff;color:#000;border-bottom:2px solid #000}\n  .eyebrow,.sub{color:#333}\n  form,.btn,footer .noprint{display:none}\n  .verdict{background:#fff;color:#000;border:2px solid #000}\n  .verdict h2,.verdict p,.verdict .vlab{color:#000}\n  section,.card,.ruler{break-inside:avoid}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n.route.im{border-left-color:var(--navy)}\n.route.im h3{color:var(--navy)}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"wrap\">\n    <p class=\"eyebrow\">Atenção Primária · SUS · Betim/MG</p>\n    <h1>Hipovitaminose D:<br>quando repor e com o que repor</h1>\n    <p class=\"sub\">Aplica o alvo correto conforme o paciente pertença ou não a grupo de risco, calcula a dose de ataque e a manutenção, checa contraindicações à reposição e — o ponto crítico — mostra <b>o que existe e o que não existe no SUS</b>. Baseado no <b>Posicionamento SBPC/ML–SBEM</b>, na <b>diretriz da Endocrine Society de 2024</b> e na RENAME 2024.</p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n<form id=\"f\" autocomplete=\"off\">\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">01</span><span class=\"stitle\">Paciente</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">Sexo</span><select id=\"sexo\"><option value=\"F\">Feminino</option><option value=\"M\">Masculino</option></select></label>\n        <label><span class=\"lab\">Idade <span class=\"unit\">anos</span></span><input type=\"number\" id=\"idade\" step=\"0.1\" min=\"0\" max=\"120\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Peso <span class=\"unit\">kg</span></span><input type=\"number\" id=\"peso\" step=\"0.1\" min=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Altura <span class=\"unit\">cm</span></span><input type=\"number\" id=\"altura\" step=\"0.5\" min=\"30\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"checks\" style=\"margin-top:10px\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_gest\" data-txt=\"gestante\"><span>Gestante</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_lact\" data-txt=\"lactante\"><span>Lactante</span></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">02</span><span class=\"stitle\">Laboratório</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">25(OH)D <span class=\"unit\">ng/mL</span></span><input type=\"number\" id=\"vitd\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Cálcio total <span class=\"unit\">mg/dL</span></span><input type=\"number\" id=\"ca\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Albumina <span class=\"unit\">g/dL</span></span><input type=\"number\" id=\"alb\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Fósforo <span class=\"unit\">mg/dL</span></span><input type=\"number\" id=\"p\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">PTH <span class=\"unit\">pg/mL</span></span><input type=\"number\" id=\"pth\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Fosfatase alcalina <span class=\"unit\">U/L</span></span><input type=\"number\" id=\"fa\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Creatinina <span class=\"unit\">mg/dL</span></span><input type=\"number\" id=\"cr\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">TFG estimada <span class=\"unit\">mL/min/1,73m²</span></span><input type=\"number\" id=\"tfg\" step=\"1\" placeholder=\"—\"></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">03</span><span class=\"stitle\">Grupos de risco — definem o alvo de 30 a 60 ng/mL</span></div>\n    <div class=\"sbody\">\n      <p style=\"font-size:13px;color:var(--slate);margin:0 0 9px\">Sem nenhum item marcado, o alvo aplicado é o da população geral saudável: acima de 20 ng/mL.</p>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_osteopor\" data-txt=\"osteoporose primária ou secundária\"><span>Osteoporose</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_osteomal\" data-txt=\"osteomalácia ou raquitismo\"><span>Osteomalácia / raquitismo</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_fratura\" data-txt=\"fratura por fragilidade ou quedas recorrentes\"><span>Fratura por fragilidade / quedas</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_hpt2\" data-txt=\"hiperparatireoidismo secundário\"><span>Hiperparatireoidismo secundário</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_drc\" data-txt=\"doença renal crônica\"><span>Doença renal crônica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco absor\" id=\"r_maabs\" data-txt=\"síndrome de má absorção\"><span>Síndrome de má absorção</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco absor\" id=\"r_bar\" data-txt=\"cirurgia bariátrica\"><span>Cirurgia bariátrica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco absor\" id=\"r_dii\" data-txt=\"doença inflamatória intestinal\"><span>Doença inflamatória intestinal</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco absor\" id=\"r_hepato\" data-txt=\"hepatopatia crônica\"><span>Hepatopatia crônica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco farmaco\" id=\"r_anticonv\" data-txt=\"uso de anticonvulsivante, glicocorticoide ou antirretroviral\"><span>Anticonvulsivante / corticoide / antirretroviral</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_neopl\" data-txt=\"neoplasia maligna\"><span>Neoplasia maligna</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_sarco\" data-txt=\"sarcopenia\"><span>Sarcopenia</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"risco\" id=\"r_dm\" data-txt=\"diabetes\"><span>Diabetes</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"r_solar\"><span>Baixa exposição solar ou contraindicação a ela</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"r_pele\"><span>Pele de fototipo alto</span></label>\n      </div>\n      <p style=\"font-size:12px;color:var(--slate);margin:11px 0 0\">Baixa exposição solar, obesidade e fototipo alto são indicações de dosagem, mas o Posicionamento não firma evidência para manter valores entre 30 e 60 ng/mL nesses grupos isoladamente.</p>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">04</span><span class=\"stitle\">Contraindicações e cautelas</span></div>\n    <div class=\"sbody\">\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"ci\" id=\"ci_granulo\" data-txt=\"doença granulomatosa (sarcoidose, tuberculose, histoplasmose) ou linfoma\"><span>Sarcoidose, tuberculose ou linfoma</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"ci\" id=\"ci_hpt1\" data-txt=\"hiperparatireoidismo primário\"><span>Hiperparatireoidismo primário</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"ci\" id=\"ci_hipercalciuria\" data-txt=\"hipercalciúria ou nefrolitíase de repetição\"><span>Hipercalciúria / nefrolitíase</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"ci\" id=\"ci_hipersens\" data-txt=\"hipersensibilidade ao colecalciferol\"><span>Hipersensibilidade ao colecalciferol</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"ci_tiazid\"><span>Uso de diurético tiazídico</span></label>\n      </div>\n      <div class=\"grouplab\">Disponibilidade local</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"d_remume\"><span>Colecalciferol isolado padronizado na REMUME de Betim (não consta na REMUME consultada no Projeto)</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"d_cacd\"><span>Carbonato de cálcio + colecalciferol disponível na UBS (RENAME; a REMUME de Betim lista só carbonato de cálcio 1.250 mg isolado)</span></label>\n      </div>\n      <div class=\"grouplab\">Esquema de ataque</div>\n      <div class=\"radios\">\n        <label><input type=\"radio\" name=\"esq\" value=\"auto\" checked><span>Decidir pelo protocolo</span></label>\n        <label><input type=\"radio\" name=\"esq\" value=\"diario\"><span>Forçar dose diária</span></label>\n        <label><input type=\"radio\" name=\"esq\" value=\"semanal\"><span>Forçar dose semanal</span></label>\n      </div>\n    </div>\n  </section>\n\n</form>\n\n<div id=\"out\"></div>\n\n<footer>\n  <p><b>Uso profissional.</b> Ferramenta de apoio à decisão; não substitui o julgamento clínico nem a leitura da bula vigente.</p>\n  <p class=\"noprint\">Referências: Posicionamento Oficial SBPC/ML e SBEM — Intervalos de Referência da Vitamina D 25(OH)D, versão 2018 · Maeda SS et al., Recomendações da SBEM para diagnóstico e tratamento da hipovitaminose D, Arq Bras Endocrinol Metab 2014 · Demay MB et al., Vitamin D for the Prevention of Disease: An Endocrine Society Clinical Practice Guideline, J Clin Endocrinol Metab 2024 · Munns CF et al., Global Consensus Recommendations on Prevention and Management of Nutritional Rickets, 2016 · RENAME 2024 · PCDT Osteoporose.</p>\n</footer>\n</div>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst num = id => { const v = ($(id).value||'').toString().replace(',', '.').trim(); if(v==='') return null; const n = parseFloat(v); return isNaN(n)?null:n; };\nconst on = id => $(id).checked;\nconst fmt = (n,d=1) => n==null?'—':n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});\nconst esc = s => String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));\n\nfunction compute(){\n  const d={};\n  d.sexo=$('sexo').value; d.idade=num('idade'); d.peso=num('peso'); d.altura=num('altura');\n  d.vitd=num('vitd'); d.ca=num('ca'); d.alb=num('alb'); d.p=num('p');\n  d.pth=num('pth'); d.fa=num('fa'); d.cr=num('cr'); d.tfg=num('tfg');\n  d.gest=on('r_gest'); d.lact=on('r_lact');\n  d.crianca = d.idade!=null && d.idade<18;\n  d.lactente = d.idade!=null && d.idade<1;\n  d.idoso = d.idade!=null && d.idade>=60;\n\n  d.imc = (d.peso!=null&&d.altura!=null) ? d.peso/Math.pow(d.altura/100,2) : null;\n  d.obeso = d.imc!=null && d.imc>=30;\n  d.maabs = [...document.querySelectorAll('.absor:checked')].length>0;\n  d.farmaco = on('r_anticonv');\n\n  /* cálcio corrigido pela albumina */\n  d.caCorr = (d.ca!=null && d.alb!=null) ? d.ca + 0.8*(4 - d.alb) : d.ca;\n  d.hiperCa = d.caCorr!=null && d.caCorr>10.5;\n  d.hipoCa = d.caCorr!=null && d.caCorr<8.5;\n  d.faAlta = d.fa!=null && d.fa>130;\n  d.pthAlto = d.pth!=null && d.pth>65;\n  d.pBaixo = d.p!=null && d.p<2.5;\n  d.drcGrave = (d.tfg!=null && d.tfg<30) || on('r_drc');\n\n  /* grupo de risco e alvo */\n  const riscos=[...document.querySelectorAll('.risco:checked')].map(e=>e.dataset.txt);\n  if(d.idoso) riscos.push('idade igual ou superior a 60 anos');\n  d.riscos=riscos;\n  d.grupoRisco = riscos.length>0;\n  d.alvo = d.grupoRisco ? 30 : 20;\n\n  /* classificação */\n  const V=d.vitd;\n  let st='indef', label='Dosagem não informada', desc='';\n  if(V!=null){\n    if(V>100) st='toxico';\n    else if(V<10) st='grave';\n    else if(V<20) st='deficiente';\n    else if(V<30) st = d.grupoRisco ? 'insuf' : 'suficiente';\n    else if(V<=60) st='suficiente';\n    else st='alto';\n  }\n  if(st==='grave'){ label='Deficiência grave de vitamina D'; desc='Abaixo de 10 ng/mL há risco concreto de raquitismo na criança e de osteomalácia no adulto, com dor óssea, fraqueza muscular proximal e fraturas. Repor e investigar má absorção.'; }\n  else if(st==='deficiente'){ label='Deficiência de vitamina D'; desc='Valor abaixo de 20 ng/mL caracteriza deficiência em qualquer perfil, com ou sem fator de risco. Há indicação de reposição.'; }\n  else if(st==='insuf'){ label='Insuficiência para o grupo de risco'; desc='Entre 20 e 30 ng/mL o valor é adequado para a população geral, mas insuficiente para este paciente, que pertence a grupo de risco com alvo entre 30 e 60 ng/mL.'; }\n  else if(st==='suficiente'){ label='Vitamina D suficiente'; desc = d.grupoRisco ? 'Valor dentro da faixa de 30 a 60 ng/mL recomendada para grupos de risco.' : 'Acima de 20 ng/mL é o desejável para a população geral saudável. Desde a revisão do Posicionamento, valores entre 20 e 30 ng/mL deixaram de ser classificados como insuficiência.'; }\n  else if(st==='alto'){ label='Acima da faixa recomendada'; desc='Entre 60 e 100 ng/mL não há benefício adicional demonstrado. Reveja a dose em uso e suspenda a suplementação desnecessária.'; }\n  else if(st==='toxico'){ label='Risco de intoxicação'; desc='Acima de 100 ng/mL há risco de hipercalcemia e intoxicação. Suspender imediatamente a suplementação, dosar cálcio e calciúria e reavaliar.'; }\n  d.st=st; d.label=label; d.desc=desc;\n  d.repor = ['grave','deficiente','insuf'].includes(st);\n\n  d.cis=[...document.querySelectorAll('.ci:checked')].map(e=>e.dataset.txt);\n  if(d.hiperCa) d.cis.push('hipercalcemia (cálcio corrigido acima de 10,5 mg/dL)');\n  d.bloqueado = d.repor && d.cis.length>0;\n\n  /* dose */\n  let fator=1, just=[];\n  if(d.obeso){ fator=Math.max(fator,2); just.push('obesidade, pelo sequestro da vitamina no tecido adiposo'); }\n  if(d.maabs){ fator=Math.max(fator,3); just.push('má absorção intestinal'); }\n  if(d.farmaco){ fator=Math.max(fator,2); just.push('indução do catabolismo hepático pelo fármaco em uso'); }\n  d.fator=fator; d.justFator=just;\n\n  const esq = document.querySelector('input[name=esq]:checked').value;\n  d.diaria = esq==='diario' ? true : (esq==='semanal' ? false : (d.idade!=null && d.idade>=50));\n  d.esqForcado = esq!=='auto';\n  return d;\n}\n\nfunction prescricao(d){\n  const L=[];\n  const src = on('d_remume') ? 'REMUME municipal' : 'aquisição pelo paciente — não consta da RENAME';\n\n  if(d.lactente){\n    L.push('COLECALCIFEROL solução oral — apresentações usuais de 200 UI/gota ou 500 UI/gota');\n    L.push('');\n    L.push('ATAQUE: 2.000 UI por via oral, uma vez ao dia, durante 12 semanas.');\n    L.push('MANUTENÇÃO: 400 UI por via oral, uma vez ao dia, mantida durante todo o primeiro ano.');\n    L.push('');\n    L.push('Associar cálcio elementar 30 a 75 mg/kg/dia por via oral, fracionado em 3 tomadas,');\n    L.push('durante o ataque — a mineralização óssea consome cálcio rapidamente e a reposição');\n    L.push('isolada de vitamina D pode precipitar hipocalcemia sintomática.');\n    L.push('');\n    L.push('Conferir no rótulo do frasco quantas UI correspondem a 1 gota: a concentração varia');\n    L.push('entre fabricantes e o erro de conversão é a causa mais comum de subdose ou superdose.');\n    return L;\n  }\n  if(d.crianca){\n    const ataque = d.idade<12 ? 3000 : 6000;\n    L.push('COLECALCIFEROL — solução oral ou cápsula');\n    L.push('');\n    L.push(`ATAQUE: ${ataque.toLocaleString('pt-BR')} UI por via oral, uma vez ao dia, durante 12 semanas.`);\n    L.push('MANUTENÇÃO: 600 UI por via oral, uma vez ao dia, por tempo indeterminado.');\n    L.push('');\n    L.push('Associar cálcio elementar 500 mg/dia por via oral durante o ataque.');\n    L.push('Redosar 25(OH)D, cálcio, fósforo e fosfatase alcalina ao final das 12 semanas.');\n    return L;\n  }\n\n  const ataqueSem = 50000*d.fator;\n  const ataqueDia = Math.round(7000*d.fator);\n  const manut = d.grupoRisco ? 2000*d.fator : 1000*d.fator;\n  L.push('COLECALCIFEROL — cápsula ou comprimido');\n  L.push(`Origem no SUS: ${src}.`);\n  L.push('');\n  L.push('FASE DE ATAQUE — 8 semanas');\n  if(d.diaria){\n    L.push(`Tomar ${ataqueDia.toLocaleString('pt-BR')} UI por via oral, uma vez ao dia, junto da maior refeição do dia,`);\n    L.push('durante 8 semanas.');\n    L.push(`Dose acumulada no ataque: ${(ataqueDia*56).toLocaleString('pt-BR')} UI.`);\n  } else {\n    L.push(`Tomar ${ataqueSem.toLocaleString('pt-BR')} UI por via oral, uma vez por semana, junto de uma refeição gordurosa,`);\n    L.push('durante 8 semanas (8 doses no total).');\n    L.push(`Dose acumulada no ataque: ${(ataqueSem*8).toLocaleString('pt-BR')} UI.`);\n  }\n  L.push('');\n  L.push('MANUTENÇÃO — a partir da 9ª semana');\n  L.push(`Tomar ${manut.toLocaleString('pt-BR')} UI por via oral, uma vez ao dia, de forma contínua.`);\n  L.push('');\n  L.push('A vitamina D é lipossolúvel: administrar sempre junto de refeição com gordura');\n  L.push('aumenta significativamente a absorção.');\n  if(d.fator>1) L.push(`Dose multiplicada por ${d.fator} em razão de: ${d.justFator.join('; ')}.`);\n  return L;\n}\n\nfunction render(){\n  const d=compute(); const o=$('out');\n  if(d.vitd==null){ o.innerHTML=`<div class=\"empty\"><b>Aguardando o exame</b>Informe a 25(OH)D em ng/mL. Marque antes os grupos de risco: eles mudam o alvo de 20 para 30 ng/mL e, com isso, a própria conclusão.</div>`; return; }\n  let h=''; const row=(a,b,c)=>`<tr><td>${a}</td><td class=\"num\">${b}</td><td>${c}</td></tr>`;\n\n  h += `<div class=\"verdict\"><p class=\"vlab\">Conclusão diagnóstica</p><h2>${esc(d.label)}</h2><p>${esc(d.desc)}</p><span class=\"cid\">Alvo aplicado · ${d.grupoRisco?'30 a 60 ng/mL (grupo de risco)':'acima de 20 ng/mL (população geral)'}</span></div>`;\n\n  const segs=[['Grave','&lt; 10 ng/mL'],['Deficiência','10 a 20'],['Adequado p/ população geral','20 a 30'],['Alvo de grupo de risco','30 a 60'],['Excesso / toxicidade','&gt; 60']];\n  let pos = d.vitd<10?0:(d.vitd<20?1:(d.vitd<30?2:(d.vitd<=60?3:4)));\n  h += `<div class=\"ruler\"><h3>Faixas do Posicionamento SBPC/ML–SBEM</h3><div class=\"track\">`;\n  segs.forEach((s,i)=>{h+=`<div class=\"seg ${i===pos?'here on':''}\"><div class=\"segbar\"></div></div>`;});\n  h += `</div><div class=\"track\" style=\"gap:3px\">`;\n  segs.forEach((s,i)=>{h+=`<div class=\"seg ${i===pos?'here':''}\"><div class=\"segtxt\"><b>${s[0]}</b><br>${s[1]}</div></div>`;});\n  h += `</div><p class=\"rulernote\">25(OH)D informada: <b>${fmt(d.vitd,1)} ng/mL</b>.${d.grupoRisco?` Grupo de risco por: ${esc(d.riscos.join('; '))}.`:' Nenhum fator de risco marcado.'}</p></div>`;\n\n  h += `<div class=\"card\"><h3>Leitura dos exames</h3><div class=\"inner\"><table><thead><tr><th>Parâmetro</th><th>Valor</th><th>Leitura</th></tr></thead><tbody>`;\n  if(d.caCorr!=null) h += row('Cálcio'+(d.alb!=null?' corrigido pela albumina':' total'), fmt(d.caCorr,2)+' mg/dL', d.hiperCa?'<span class=\"tagbad\">Hipercalcemia — contraindica a reposição até esclarecer</span>':(d.hipoCa?'<span class=\"tagmid\">Hipocalcemia — repor cálcio junto da vitamina D</span>':'<span class=\"tagok\">Normal</span>'));\n  if(d.pth!=null) h += row('PTH', fmt(d.pth,0)+' pg/mL', d.pthAlto?(d.hiperCa?'<span class=\"tagbad\">PTH alto com cálcio alto — investigar hiperparatireoidismo primário antes de repor</span>':'<span class=\"tagmid\">Hiperparatireoidismo secundário à carência — tende a normalizar com a reposição</span>'):'<span class=\"tagok\">Normal</span>');\n  if(d.fa!=null) h += row('Fosfatase alcalina', fmt(d.fa,0)+' U/L', d.faAlta?'<span class=\"tagmid\">Elevada — sugere doença óssea metabólica em atividade</span>':'<span class=\"tagok\">Normal</span>');\n  if(d.p!=null) h += row('Fósforo', fmt(d.p,2)+' mg/dL', d.pBaixo?'<span class=\"tagmid\">Baixo — compõe o quadro de osteomalácia</span>':'<span class=\"tagok\">Normal</span>');\n  if(d.tfg!=null) h += row('TFG estimada', fmt(d.tfg,0), d.tfg<30?'<span class=\"tagbad\">Abaixo de 30 — a 1-alfa-hidroxilação renal está comprometida</span>':'<span class=\"tagok\">Preservada para hidroxilação renal</span>');\n  if(d.imc!=null) h += row('IMC', fmt(d.imc,1)+' kg/m²', d.obeso?'<span class=\"tagmid\">Obesidade — sequestro adiposo exige dose maior</span>':'<span class=\"tagok\">—</span>');\n  h += `</tbody></table></div></div>`;\n\n  let flags='';\n  if(d.st==='toxico') flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Suspender a suplementação agora</b>Acima de 100 ng/mL há risco de hipercalcemia, hipercalciúria, nefrolitíase e lesão renal. Suspenda o colecalciferol, dose cálcio total e albumina, calciúria de 24 horas, função renal e PTH, e oriente hidratação. Reavalie em 4 a 8 semanas: a meia-vida longa faz a normalização demorar.</div></div>`;\n  if(d.st==='alto') flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Acima da faixa recomendada</b>Não há benefício demonstrado acima de 60 ng/mL. Reveja a dose em uso, suspenda suplementos não prescritos e reavalie em 3 meses.</div></div>`;\n  if(d.bloqueado) flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Reposição contraindicada neste momento</b>Registrado: ${esc(d.cis.join('; '))}. Na doença granulomatosa e no linfoma, macrófagos e células neoplásicas expressam 1-alfa-hidroxilase fora do controle do PTH e convertem o substrato em calcitriol de forma desregulada — repor vitamina D pode precipitar hipercalcemia grave. No hiperparatireoidismo primário, esclareça o diagnóstico e a conduta cirúrgica antes de suplementar.</div></div>`;\n  if(d.drcGrave && d.repor) flags += `<div class=\"flag warn\"><span class=\"ic\">→</span><div><b>Doença renal crônica</b>Com TFG abaixo de 30 a hidroxilação renal está comprometida e o colecalciferol isolado não gera calcitriol suficiente. A conduta passa por calcitriol ou alfacalcidol, que são do Componente Especializado e seguem o PCDT de Osteodistrofia Renal — encaminhe à nefrologia. Repor o substrato ainda é válido, mas não substitui o análogo ativo.</div></div>`;\n  if(on('ci_tiazid') && d.repor) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Diurético tiazídico em uso</b>Tiazídicos reduzem a excreção urinária de cálcio e potencializam o risco de hipercalcemia durante a reposição. Dose cálcio em 4 semanas.</div></div>`;\n  if(d.hipoCa && d.repor) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Hipocalcemia associada</b>Reponha cálcio junto da vitamina D. Corrigir apenas a vitamina D acelera a mineralização óssea e consome o cálcio circulante, agravando a hipocalcemia — a chamada síndrome do osso faminto.</div></div>`;\n  if(d.faAlta && d.pthAlto && d.vitd<10) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Padrão de osteomalácia</b>25(OH)D muito baixa, fosfatase alcalina e PTH elevados e fósforo baixo compõem o quadro clássico. Procure dor óssea difusa, fraqueza muscular proximal, marcha anserina e pseudofraturas de Looser em radiografia de bacia e fêmures.</div></div>`;\n  if(!d.grupoRisco && d.st==='suficiente' && d.vitd<30) flags += `<div class=\"flag info\"><span class=\"ic\">i</span><div><b>Mudança de referência que ainda gera confusão</b>Valores entre 20 e 30 ng/mL <b>deixaram de ser insuficiência</b> para a população geral desde a revisão do Posicionamento SBPC/ML–SBEM. Muitos laudos ainda trazem o corte antigo de 30 ng/mL e induzem tratamento desnecessário. Este paciente não tem indicação de reposição.</div></div>`;\n  if(flags) h += flags;\n\n  if(d.st==='indef'){ o.innerHTML=h; return; }\n\n  if(!d.repor){\n    h += `<div class=\"card\"><h3>${d.st==='toxico'||d.st==='alto'?'Suspender e reavaliar':'Sem indicação de reposição'}</h3><div class=\"inner\">`;\n    if(d.st==='suficiente') h += `<p>O valor está adequado para o alvo aplicável a este paciente. Suplementar sem deficiência não traz benefício demonstrado e adiciona custo e risco.</p><p>A Endocrine Society, em 2024, foi além: recomenda <b>contra o rastreamento de rotina</b> da 25(OH)D em qualquer das populações estudadas, inclusive obesos e pessoas de pele escura, por não haver evidência de limiar ótimo para prevenção de doença. Orientação não medicamentosa segue válida: exposição solar regular e ingestão adequada.</p>`;\n    else h += `<p>Suspenda a suplementação e siga o alerta acima.</p>`;\n    h += `</div></div>`;\n  } else if(d.bloqueado){\n    h += `<div class=\"card route\"><h3>Reposição suspensa</h3><div class=\"inner\"><p><b>Contraindicação registrada:</b> ${esc(d.cis.join('; '))}.</p><p>Esclareça e trate a condição de base antes de repor. Em doença granulomatosa ativa, alguns pacientes toleram doses baixas sob monitoramento de cálcio sérico e urinário a cada 4 semanas — decisão que pertence ao especialista, não à atenção básica.</p></div></div>`;\n  } else {\n    h += `<div class=\"card route oral\"><h3>Prescrição</h3><div class=\"inner\">`;\n    h += `<pre class=\"rx\">${prescricao(d).map(esc).join('\\n')}</pre>`;\n    if(!d.esqForcado && !d.crianca) h += `<p style=\"margin-top:11px;font-size:12.5px;color:var(--slate)\">Esquema ${d.diaria?'diário':'semanal'} escolhido automaticamente: ${d.diaria?'a Endocrine Society recomenda dose diária em vez de dose alta intermitente a partir dos 50 anos, porque doses grandes e espaçadas elevam a 24,25-di-hidroxivitamina D inativa e a relação risco-benefício piora no idoso.':'abaixo dos 50 anos a dose semanal é aceitável e favorece a adesão durante o ataque.'}</p>`;\n    h += `<button class=\"btn\" type=\"button\" onclick=\"copiar()\">Copiar prescrição</button></div></div>`;\n\n    /* --- acesso: o cálculo que expõe a inviabilidade do CBAF --- */\n    let ac='';\n    if(!on('d_remume')){\n      const alvoDia = d.crianca ? (d.lactente?2000:(d.idade<12?3000:6000)) : (d.diaria?Math.round(7000*d.fator):Math.round(50000*d.fator/7));\n      const cp400 = Math.ceil(alvoDia/400);\n      const caMg = cp400*500;\n      ac += `<div class=\"flag stop\" style=\"margin:0 0 12px\"><span class=\"ic\">✕</span><div><b>Colecalciferol isolado não consta da RENAME 2024</b>O que existe no Componente Básico é apenas a <b>associação carbonato de cálcio + colecalciferol</b>, nas apresentações de 500 mg de cálcio + 200 UI, 500 mg de cálcio + 400 UI e 600 mg de cálcio + 400 UI.</div></div>`;\n      ac += `<p>Por que a associação não resolve o ataque, em números deste caso:</p>`;\n      ac += `<pre class=\"rx\">Dose diária de vitamina D pretendida: ${alvoDia.toLocaleString('pt-BR')} UI\nMaior apresentação do CBAF: 600 mg de cálcio + 400 UI por comprimido\nComprimidos necessários por dia: ${cp400}\nCarga de cálcio elementar embutida: ${caMg.toLocaleString('pt-BR')} mg/dia</pre>`;\n      ac += `<p>Uma carga diária dessa magnitude de cálcio ultrapassa com folga o limite superior tolerável de 2.000 a 2.500 mg e traz risco de hipercalciúria, nefrolitíase e — conforme a literatura de suplementação isolada de cálcio — possível efeito cardiovascular adverso. <b>A associação serve à manutenção e à prevenção, não ao tratamento da deficiência.</b></p>`;\n      ac += `<p>Caminhos reais, em ordem de esforço: verificar a <b>REMUME de Betim</b>, já que os municípios podem ampliar o elenco além da RENAME; verificar se o colecalciferol está contemplado em algum protocolo local vinculado à osteoporose; ou orientar a compra, cujo custo mensal é baixo mesmo para as doses de ataque. Se houver barreira financeira intransponível e doença óssea documentada, o caso comporta solicitação administrativa à Assistência Farmacêutica municipal com relatório fundamentado — e é aqui que a fosfatase alcalina, o PTH e a radiografia fazem diferença no pedido.</p>`;\n    } else {\n      ac += `<p>Colecalciferol isolado marcado como padronizado na REMUME de Betim — dispense pela farmácia da UBS conforme a apresentação municipal. Confira a concentração disponível antes de definir o número de cápsulas.</p>`;\n      ac += `<p style=\"font-size:12.5px;color:var(--slate)\">Lembre-se de que o medicamento não consta da RENAME 2024: a padronização é municipal e pode ser descontinuada. Confirme o estoque antes de prometer o tratamento ao paciente.</p>`;\n    }\n    if(d.hipoCa||d.crianca) ac += `<p>Para a associação de cálcio, o CBAF oferece carbonato de cálcio + colecalciferol nas três apresentações citadas — adequadas justamente para esse papel complementar.</p>`;\n    h += `<div class=\"card\"><h3>Acesso no SUS</h3><div class=\"inner\">${ac}</div></div>`;\n\n    /* --- escada de apresentações --- */\n    {\n      const alvoDia = d.crianca ? (d.lactente?2000:(d.idade<12?3000:6000)) : (d.diaria?Math.round(7000*d.fator):Math.round(50000*d.fator/7));\n      const manutDia = d.crianca ? (d.lactente?400:600) : (d.grupoRisco?2000*d.fator:1000*d.fator);\n      const caps50k = Math.ceil(50000*d.fator/50000)*8;\n      let t = `<div class=\"card\"><h3>Apresentações e alternativas, da mais acessível à menos</h3><div class=\"inner\">`;\n      t += `<table><thead><tr><th>Ordem</th><th>Apresentação e nomes</th><th>Serve para</th><th>Acesso e custo</th></tr></thead><tbody>`;\n      t += `<tr><td class=\"num\">1</td><td><b>Carbonato de cálcio + colecalciferol</b> — 500 mg Ca + 200 UI, 500 mg Ca + 400 UI, 600 mg Ca + 400 UI</td><td>Manutenção e prevenção apenas. <b>Não serve para o ataque</b></td><td class=\"tagok\">CBAF — gratuito na UBS</td></tr>`;\n      t += `<tr><td class=\"num\">2</td><td><b>Colecalciferol genérico</b> — cápsula mole ou comprimido revestido<br><span style=\"color:var(--slate)\">Prati-Donaduzzi, EMS, Nova Química, Biolab Genéricos, Geolab, Pharlab, Legrand, Teuto, Medley, Sandoz, Vitamedic, Natulab, Cimed</span></td><td>Ataque e manutenção, nas concentrações de 1.000, 2.000, 7.000, 10.000 e 50.000 UI</td><td class=\"tagok\">Compra pelo paciente — <b>é a via mais barata fora do SUS</b></td></tr>`;\n      t += `<tr><td class=\"num\">3</td><td><b>Colecalciferol solução oral em gotas</b> — 200 UI/gota ou 500 UI/gota</td><td>Lactentes e crianças pequenas; permite titular a dose</td><td class=\"tagok\">Compra pelo paciente — custo baixo, frasco rende meses</td></tr>`;\n      t += `<tr><td class=\"num\">4</td><td><b>Marcas de referência</b><br><span style=\"color:var(--slate)\">Addera D3 (Hypera), Depura (Sanofi), Alta D (Eurofarma), D3Caps, Vitamina D Cimed</span></td><td>Mesmas indicações do genérico</td><td class=\"tagmid\">Compra pelo paciente — sem vantagem clínica sobre o genérico</td></tr>`;\n      if(d.drcGrave) t += `<tr><td class=\"num\">5</td><td><b>Calcitriol</b> e <b>alfacalcidol</b></td><td>Doença renal crônica, quando a hidroxilação renal está comprometida</td><td class=\"tagmid\">CEAF — exige LME e PCDT específico, via nefrologia</td></tr>`;\n      t += `</tbody></table>`;\n      t += `<p><b>Quantidade necessária neste caso, para orientar a compra:</b></p>`;\n      t += `<pre class=\"rx\">Ataque, ${d.crianca?'12 semanas':'8 semanas'}\n  - ${d.diaria||d.crianca ? `${alvoDia.toLocaleString('pt-BR')} UI/dia` : `${(50000*d.fator).toLocaleString('pt-BR')} UI/semana`}\n  - ${d.crianca ? 'preferir solução em gotas ou cápsula de menor concentração para fracionar'\n      : (d.diaria ? `equivale a ${Math.ceil(alvoDia/2000)} cápsula(s) de 2.000 UI por dia, ou ${Math.ceil(alvoDia/7000)} de 7.000 UI`\n                  : `${8*d.fator} cápsula(s) de 50.000 UI no total — 1 a 2 caixas`)}\n\nManutenção, contínua\n  - ${manutDia.toLocaleString('pt-BR')} UI/dia\n  - equivale a ${Math.ceil(manutDia/1000)} cápsula(s) de 1.000 UI ou ${Math.ceil(manutDia/2000)} de 2.000 UI por dia\n  - uma caixa de 30 cápsulas cobre cerca de ${Math.floor(30/Math.max(1,Math.ceil(manutDia/2000)))} dias na concentração de 2.000 UI</pre>`;\n      t += `<p style=\"font-size:12.5px;color:var(--slate)\">O determinante do custo é o número de unidades, não o preço unitário: um ataque semanal com 50.000 UI consome 8 cápsulas e costuma sair por menos que o mesmo ataque em cápsulas diárias de 7.000 UI, que consome 56. Para valores correntes, consulte a tabela CMED da Anvisa ou um comparador de farmácias — o colecalciferol tem mais de setecentas apresentações registradas e a dispersão de preço entre genérico e referência é grande.</p>`;\n      t += `<p style=\"font-size:12.5px;color:var(--slate)\">O Farmácia Popular não cobre colecalciferol isolado. A linha de osteoporose do programa contempla alendronato de sódio; a associação de cálcio com vitamina D já esteve na relação, então vale confirmar a lista oficial vigente antes de orientar o paciente a procurar farmácia credenciada.</p>`;\n      t += `</div></div>`;\n      h += t;\n    }\n\n    /* monitoramento */\n    h += `<div class=\"card\"><h3>Monitoramento</h3><div class=\"inner\"><table><thead><tr><th>Momento</th><th>O que avaliar</th><th>Conduta</th></tr></thead><tbody>`;\n    h += row('4 semanas','Cálcio total e albumina','Rastrear hipercalcemia, sobretudo com tiazídico, doença granulomatosa oculta ou dose multiplicada');\n    h += row('8 a 12 semanas','25(OH)D','Não redosar antes: o equilíbrio após mudança de dose leva cerca de 3 meses. Redosar cedo gera ajuste equivocado');\n    if(d.pthAlto) h += row('3 a 6 meses','PTH','Deve cair com a correção da carência. Se persistir elevado com cálcio normal, procure outras causas de hiperparatireoidismo secundário');\n    if(d.faAlta) h += row('3 a 6 meses','Fosfatase alcalina','Queda progressiva acompanha a remineralização óssea');\n    h += row('Anual, se em manutenção','25(OH)D e cálcio','Apenas em quem tem indicação persistente de suplementação — não é exame de rotina populacional');\n    h += `</tbody></table><p style=\"font-size:12.5px;color:var(--slate)\">Orientação não medicamentosa em paralelo: exposição solar de braços e pernas por 5 a 15 minutos, algumas vezes por semana, fora do horário de pico; peixes gordurosos, gema de ovo e alimentos fortificados. Em fototipo alto o tempo necessário é substancialmente maior.</p></div></div>`;\n\n    /* investigação */\n    let inv=[];\n    if(d.st==='grave') inv.push('<b>Deficiência grave exige explicação.</b> Abaixo de 10 ng/mL, investigue má absorção ativamente: doença celíaca (antitransglutaminase IgA com IgA total), doença inflamatória intestinal, insuficiência pancreática exócrina, cirurgia bariátrica prévia e hepatopatia colestática.');\n    if(d.faAlta||d.pthAlto) inv.push('Complete o painel osteometabólico: cálcio e fósforo séricos, cálcio urinário de 24 horas, PTH, função renal e fosfatase alcalina. Radiografia de bacia e fêmures se houver dor óssea ou fraqueza proximal.');\n    inv.push('Reveja fármacos que aceleram o catabolismo da vitamina D: fenitoína, fenobarbital, carbamazepina, rifampicina, glicocorticoides e alguns antirretrovirais.');\n    if(d.idoso) inv.push('No idoso, associe avaliação de risco de queda e densitometria óssea conforme indicação — a hipovitaminose D contribui para fraqueza muscular proximal e instabilidade postural, não apenas para a perda de massa óssea.');\n    if(d.gest||d.lact) inv.push('Na gestação e lactação, a reserva materna determina a do recém-nascido. A Endocrine Society recomenda suplementação empírica na gestação, e o lactente em aleitamento exclusivo precisa de 400 UI/dia independentemente do status materno.');\n    if(d.obeso) inv.push('Na obesidade, a 25(OH)D total é menor por diluição em maior volume de distribuição e sequestro adiposo, sem que isso signifique necessariamente carência funcional. A Endocrine Society não recomenda rastreamento por obesidade isolada.');\n    h += `<div class=\"card\"><h3>Investigação e contexto</h3><div class=\"inner\"><ul>${inv.map(x=>`<li>${x}</li>`).join('')}</ul></div></div>`;\n  }\n  o.innerHTML=h;\n}\n\nfunction copiar(){\n  const t=[...document.querySelectorAll('#out .rx')].map(e=>e.innerText).join('\\n\\n');\n  navigator.clipboard.writeText(t).then(()=>{\n    document.querySelectorAll('#out .btn').forEach(b=>{b.textContent='Prescrição copiada';setTimeout(()=>b.textContent='Copiar prescrição',2000);});\n  });\n}\ndocument.getElementById('f').addEventListener('input', render);\ndocument.getElementById('f').addEventListener('change', render);\nconst _tw=()=>{document.querySelectorAll('#out table').forEach(t=>{\n  if(!t.parentElement.classList.contains('tw')){\n    const w=document.createElement('div'); w.className='tw';\n    t.parentNode.insertBefore(w,t); w.appendChild(t);}});};\nnew MutationObserver(_tw).observe(document.getElementById('out'),{childList:true,subtree:true});\n\nrender();\n<\/script>\n<script>(function(){function _h(){try{parent.postMessage({embId:'vitd_full',embH:document.documentElement.scrollHeight},'*')}catch(e){}}window.addEventListener('load',_h);try{new ResizeObserver(_h).observe(document.body)}catch(e){setInterval(_h,800)}document.addEventListener('input',function(){setTimeout(_h,50)});})();<\/script></body>\n</html>\n";
EMB_HTML["b12_full"] = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Reposição de vitamina B12 — calculadora clínica SUS</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{\n  --bordo:#5C1A2B;\n  --bordo-deep:#3B0F1A;\n  --bone:#F7F4EF;\n  --paper:#FFFDFA;\n  --ink:#1C1A19;\n  --slate:#585048;\n  --rule:#DDD4C7;\n  --teal:#1F5C58;\n  --brass:#9A6B12;\n  --crimson:#A3182B;\n  --ok:#1F5C58;\n  --surface2:#F2ECE3;\n  --hover:#F4EEE4;\n  --sel:#F6ECEE;\n  --track:#E7DFD3;\n  --rxbg:#FBF7F0;\n  --field:#FFFFFF;\n  --navy:#2E4A7D;\n  --onbordo:#F0DDE0;\n  --onbordo-dim:#DBB7BE;\n  --onbordo-strong:#FFFFFF;\n  --headfg:#E3D3D6;\n  --headeyebrow:#C9A9AF;\n  --stopbg:#FBEDEE; --stopbd:#E0B6BC; --stopfg:#6E1220;\n  --warnbg:#FBF3E2; --warnbd:#E2CE9E; --warnfg:#5F420A;\n  --infobg:#EAF1F0; --infobd:#AFC9C6; --infofg:#123C39;\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:env(safe-area-inset-bottom,0px);\n}\n\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n    --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n    --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n    --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n    --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n    --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n    --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n    --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n    --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n    --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n  --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n  --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n  --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n  --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n  --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n  --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n  --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n  --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n  --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\n.tw{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:0 0 10px}\n.tw table{margin:0;min-width:100%}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  background:var(--bone);\n  color:var(--ink);\n  font-family:\"Public Sans\",system-ui,sans-serif;\n  font-size:15px;\n  line-height:1.5;\n  -webkit-font-smoothing:antialiased;\n}\n.wrap{max-width:860px;margin:0 auto;padding:0 16px 80px}\n\n/* ---------- header ---------- */\nheader{\n  background:var(--bordo-deep);\n  color:var(--bone);\n  padding:26px 0 22px;\n  margin-bottom:22px;\n  border-bottom:4px solid var(--bordo);\n}\nheader .wrap{padding-bottom:0}\n.eyebrow{\n  font-family:\"IBM Plex Mono\",monospace;\n  font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;\n  color:var(--headeyebrow);margin:0 0 8px;\n}\nh1{\n  font-family:\"Fraunces\",serif;\n  font-weight:600;font-size:clamp(26px,6vw,38px);\n  line-height:1.05;margin:0 0 10px;letter-spacing:-.01em;\n}\n.sub{margin:0;font-size:13.5px;color:var(--headfg);max-width:62ch}\n.sub b{color:var(--onbordo-strong);font-weight:600}\n\n/* ---------- sections ---------- */\nsection{\n  background:var(--paper);\n  border:1px solid var(--rule);\n  border-radius:3px;\n  margin-bottom:14px;\n  overflow:hidden;\n}\n.shead{\n  display:flex;align-items:baseline;gap:10px;\n  padding:11px 14px;border-bottom:1px solid var(--rule);\n  background:var(--surface2);\n}\n.snum{\n  font-family:\"IBM Plex Mono\",monospace;font-size:11px;font-weight:600;\n  color:var(--bordo);letter-spacing:.08em;\n}\n.stitle{font-family:\"Fraunces\",serif;font-weight:600;font-size:17px;letter-spacing:-.01em}\n.sbody{padding:14px}\n\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:10px 12px}\nlabel{display:block}\n.lab{\n  display:block;font-size:11px;font-weight:600;letter-spacing:.04em;\n  text-transform:uppercase;color:var(--slate);margin-bottom:3px;\n}\n.unit{font-weight:400;text-transform:none;letter-spacing:0;color:#8B8177}\ninput[type=number],input[type=text],select{\n  width:100%;padding:8px 9px;border:1px solid var(--rule);border-radius:2px;\n  background:var(--field);color:var(--ink);\n  font-family:\"IBM Plex Mono\",monospace;font-size:15px;\n}\ninput:focus,select:focus{outline:2px solid var(--bordo);outline-offset:0;border-color:var(--bordo)}\nselect{font-family:\"Public Sans\",sans-serif}\n\n.checks{display:grid;grid-template-columns:1fr;gap:2px}\n@media(min-width:640px){.checks{grid-template-columns:1fr 1fr;gap:2px 16px}}\n.chk{display:flex;gap:8px;align-items:flex-start;padding:5px 4px;border-radius:2px;cursor:pointer;font-size:13.5px;line-height:1.35}\n.chk:hover{background:var(--hover)}\n.chk input{margin:2px 0 0;accent-color:var(--bordo);width:16px;height:16px;flex:0 0 auto}\n.grouplab{\n  font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.12em;\n  text-transform:uppercase;color:var(--bordo);margin:14px 0 6px;\n  padding-bottom:4px;border-bottom:1px dotted var(--rule);\n}\n.grouplab:first-child{margin-top:0}\n\n.radios{display:flex;flex-wrap:wrap;gap:8px}\n.radios label{\n  border:1px solid var(--rule);border-radius:2px;padding:7px 11px;cursor:pointer;\n  font-size:13px;background:var(--field);display:flex;gap:7px;align-items:center;\n}\n.radios input{accent-color:var(--bordo)}\n.radios label:has(input:checked){border-color:var(--bordo);background:var(--sel);font-weight:600}\n\n/* ---------- result ---------- */\n#out{margin-top:26px}\n.verdict{\n  background:var(--bordo);color:#fff;border-radius:3px;padding:16px 16px 14px;margin-bottom:12px;\n}\n.verdict .vlab{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--onbordo-dim);margin-bottom:5px}\n.verdict h2{font-family:\"Fraunces\",serif;font-weight:600;font-size:23px;margin:0 0 6px;line-height:1.12}\n.verdict p{margin:0;font-size:13.5px;color:var(--onbordo)}\n.cid{\n  display:inline-block;margin-top:9px;font-family:\"IBM Plex Mono\",monospace;font-size:12px;\n  background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);\n  padding:3px 8px;border-radius:2px;\n}\n\n/* signature: staging ruler */\n.ruler{margin:0 0 14px;background:var(--paper);border:1px solid var(--rule);border-radius:3px;padding:14px}\n.ruler h3{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--bordo);margin:0 0 12px;font-weight:600}\n.track{display:flex;gap:3px;margin-bottom:8px}\n.seg{flex:1;position:relative}\n.segbar{height:9px;background:var(--track);border-radius:1px}\n.seg.on .segbar{background:var(--bordo)}\n.seg.here .segbar{background:var(--bordo);box-shadow:0 0 0 2px var(--paper),0 0 0 4px var(--bordo)}\n.segtxt{font-size:10.5px;line-height:1.25;color:var(--slate);margin-top:7px;padding-right:6px}\n.seg.here .segtxt{color:var(--bordo);font-weight:700}\n.rulernote{font-size:12px;color:var(--slate);margin:10px 0 0;padding-top:9px;border-top:1px dotted var(--rule)}\n\n.card{background:var(--paper);border:1px solid var(--rule);border-radius:3px;margin-bottom:12px}\n.card h3{\n  margin:0;padding:10px 14px;border-bottom:1px solid var(--rule);background:var(--surface2);\n  font-family:\"Fraunces\",serif;font-weight:600;font-size:16px;\n}\n.card .inner{padding:13px 14px}\n.card p{margin:0 0 9px}\n.card p:last-child{margin-bottom:0}\n.card ul{margin:0 0 9px;padding-left:19px}\n.card li{margin-bottom:5px}\n\n.route{border-left:4px solid var(--teal)}\n.route h3{color:var(--teal)}\n.route.oral{border-left-color:var(--bordo)}\n.route.oral h3{color:var(--bordo)}\n\n.rx{\n  font-family:\"IBM Plex Mono\",monospace;font-size:12.5px;line-height:1.65;\n  white-space:pre-wrap;background:var(--rxbg);border:1px solid var(--rule);\n  padding:12px;border-radius:2px;margin:0;overflow-x:auto;\n}\n.btn{\n  font-family:\"Public Sans\",sans-serif;font-size:13px;font-weight:600;\n  background:var(--bordo);color:#fff;border:0;border-radius:2px;\n  padding:9px 15px;cursor:pointer;margin-top:10px;\n}\n.btn:hover{background:var(--bordo-deep)}\n.btn:focus-visible{outline:2px solid var(--ink);outline-offset:2px}\n\n.flag{\n  display:flex;gap:9px;padding:10px 12px;border-radius:2px;margin-bottom:8px;font-size:13.5px;line-height:1.4;\n  border:1px solid;\n}\n.flag b{display:block;margin-bottom:2px}\n.flag.stop{background:var(--stopbg);border-color:var(--stopbd);color:var(--stopfg)}\n.flag.warn{background:var(--warnbg);border-color:var(--warnbd);color:var(--warnfg)}\n.flag.info{background:var(--infobg);border-color:var(--infobd);color:var(--infofg)}\n.flag .ic{font-family:\"IBM Plex Mono\",monospace;font-weight:600;flex:0 0 auto}\n\ntable{width:100%;border-collapse:collapse;font-size:13px;margin:0 0 10px}\nth,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--rule);vertical-align:top}\nth{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);font-weight:600}\ntd.num{font-family:\"IBM Plex Mono\",monospace}\n.tagok{color:var(--ok);font-weight:600}\n.tagbad{color:var(--crimson);font-weight:600}\n.tagmid{color:var(--brass);font-weight:600}\n\n.empty{\n  text-align:center;padding:34px 18px;color:var(--slate);\n  border:1px dashed var(--rule);border-radius:3px;background:var(--paper);\n}\n.empty b{display:block;font-family:\"Fraunces\",serif;font-size:18px;color:var(--ink);margin-bottom:5px;font-weight:600}\n\nfooter{margin-top:30px;padding-top:16px;border-top:1px solid var(--rule);font-size:11.5px;color:var(--slate);line-height:1.55}\nfooter b{color:var(--ink)}\n\n@media print{\n  body{background:#fff}\n  header{background:#fff;color:#000;border-bottom:2px solid #000}\n  .eyebrow,.sub{color:#333}\n  form,.btn,footer .noprint{display:none}\n  .verdict{background:#fff;color:#000;border:2px solid #000}\n  .verdict h2,.verdict p,.verdict .vlab{color:#000}\n  section,.card,.ruler{break-inside:avoid}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n.route.im{border-left-color:var(--navy)}\n.route.im h3{color:var(--navy)}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"wrap\">\n    <p class=\"eyebrow\">Atenção Primária · SUS · Betim/MG</p>\n    <h1>Hipovitaminose B12:<br>do limiar indeterminado à prescrição</h1>\n    <p class=\"sub\">Classifica a deficiência de cobalamina, separa o que é carência do que é falso resultado, define via e devolve a <b>prescrição completa</b> de cianocobalamina — a cianocobalamina injetável do Componente Básico (RENAME 2024: 500 mcg/mL). Baseado na <b>NICE NG239 (2024)</b>, nas diretrizes da <b>British Society for Haematology</b> e na RENAME 2024.</p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n<form id=\"f\" autocomplete=\"off\">\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">01</span><span class=\"stitle\">Paciente</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">Sexo</span><select id=\"sexo\"><option value=\"F\">Feminino</option><option value=\"M\">Masculino</option></select></label>\n        <label><span class=\"lab\">Idade <span class=\"unit\">anos</span></span><input type=\"number\" id=\"idade\" step=\"0.1\" min=\"0\" max=\"120\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Peso <span class=\"unit\">kg</span></span><input type=\"number\" id=\"peso\" step=\"0.1\" min=\"1\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"grouplab\">Situação</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"gestante\"><span>Gestante</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"lactante\"><span>Lactante</span></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">02</span><span class=\"stitle\">Dosagens e hemograma</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">B12 sérica <span class=\"unit\">pg/mL</span></span><input type=\"number\" id=\"b12\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Ácido metilmalônico <span class=\"unit\">µmol/L</span></span><input type=\"number\" id=\"mma\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Homocisteína <span class=\"unit\">µmol/L</span></span><input type=\"number\" id=\"hcy\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Folato sérico <span class=\"unit\">ng/mL</span></span><input type=\"number\" id=\"folato\" step=\"0.1\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"grouplab\">Hemograma e hemólise intramedular</div>\n      <div class=\"grid\">\n        <label><span class=\"lab\">Hb <span class=\"unit\">g/dL</span></span><input type=\"number\" id=\"hb\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">VCM <span class=\"unit\">fL</span></span><input type=\"number\" id=\"vcm\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">RDW <span class=\"unit\">%</span></span><input type=\"number\" id=\"rdw\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Plaquetas <span class=\"unit\">10³/µL</span></span><input type=\"number\" id=\"plaq\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Neutrófilos <span class=\"unit\">10³/µL</span></span><input type=\"number\" id=\"neut\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Reticulócitos <span class=\"unit\">%</span></span><input type=\"number\" id=\"retic\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">LDH <span class=\"unit\">U/L</span></span><input type=\"number\" id=\"ldh\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Bilirrubina indireta <span class=\"unit\">mg/dL</span></span><input type=\"number\" id=\"bi\" step=\"0.01\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"grouplab\">Segurança e confundidores</div>\n      <div class=\"grid\">\n        <label><span class=\"lab\">Potássio <span class=\"unit\">mEq/L</span></span><input type=\"number\" id=\"k\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Creatinina <span class=\"unit\">mg/dL</span></span><input type=\"number\" id=\"cr\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Ferritina <span class=\"unit\">ng/mL</span></span><input type=\"number\" id=\"ferritina\" step=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">TSH <span class=\"unit\">µUI/mL</span></span><input type=\"number\" id=\"tsh\" step=\"0.01\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"checks\" style=\"margin-top:8px\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"hiperseg\"><span>Neutrófilos hipersegmentados no esfregaço</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"antifi\"><span>Anti-fator intrínseco positivo</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"anticp\"><span>Anti-célula parietal positivo</span></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">03</span><span class=\"stitle\">Quadro neurológico</span></div>\n    <div class=\"sbody\">\n      <p style=\"font-size:13px;color:var(--slate);margin:0 0 9px\">Qualquer item marcado altera o esquema e a urgência: o dano neurológico pode ser irreversível se o tratamento demorar.</p>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_parest\"><span>Parestesias em bota e luva</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_prop\"><span>Perda de propriocepção ou vibratória</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_ataxia\"><span>Ataxia ou marcha instável / Romberg</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_cog\"><span>Declínio cognitivo ou confusão</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_psiq\"><span>Sintomas psiquiátricos de início recente</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"neuro\" id=\"n_optic\"><span>Neuropatia óptica</span></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">04</span><span class=\"stitle\">Causa provável e contexto</span></div>\n    <div class=\"sbody\">\n      <div class=\"grouplab\">Má absorção — indica via intramuscular</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_pa\" data-txt=\"anemia perniciosa / gastrite atrófica autoimune\"><span>Anemia perniciosa / gastrite atrófica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_gastrec\" data-txt=\"gastrectomia total ou parcial\"><span>Gastrectomia</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_bar\" data-txt=\"bypass gástrico ou cirurgia bariátrica\"><span>Bypass gástrico / bariátrica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_ileo\" data-txt=\"doença ou ressecção ileal (Crohn, tuberculose intestinal)\"><span>Doença ou ressecção ileal</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_celiaca\" data-txt=\"doença celíaca ou espru tropical\"><span>Doença celíaca / espru</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"mala\" id=\"c_panc\" data-txt=\"insuficiência pancreática exócrina\"><span>Insuficiência pancreática exócrina</span></label>\n      </div>\n\n      <div class=\"grouplab\">Causas reversíveis — permitem via oral</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_vegan\"><span>Dieta vegana ou vegetariana estrita</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_metf\"><span>Metformina em uso contínuo</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_ibp\"><span>IBP ou antagonista H2 contínuo</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_etil\"><span>Etilismo crônico</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_n2o\"><span>Exposição a óxido nitroso</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_desnut\"><span>Desnutrição / insegurança alimentar</span></label>\n      </div>\n\n      <div class=\"grouplab\">Situações que alteram a interpretação da B12 sérica</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"f_supl\"><span>Já em uso de suplemento ou injeção de B12</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"f_hepato\"><span>Hepatopatia (eleva B12 falsamente)</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"f_mielo\"><span>Síndrome mieloproliferativa (eleva B12 falsamente)</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"f_gest\"><span>Uso de contraceptivo oral (reduz B12 falsamente)</span></label>\n      </div>\n\n      <div class=\"grouplab\">Apresentação injetável disponível</div>\n      <div class=\"radios\">\n        <label><input type=\"radio\" name=\"apres\" value=\"amicored500\" checked><span>Amicored® 500 mcg/mL</span></label>\n        <label><input type=\"radio\" name=\"apres\" value=\"amicored2500\"><span>Amicored® 2.500 mcg/mL</span></label>\n        <label><input type=\"radio\" name=\"apres\" value=\"biolab\"><span>Vitamina B12 Biolab 2.000 mcg/mL</span></label>\n        <label><input type=\"radio\" name=\"apres\" value=\"bedoze\"><span>Bedoze® 5 mg/mL</span></label>\n        <label><input type=\"radio\" name=\"apres\" value=\"rubranova\"><span>Rubranova® 5.000 mcg/2 mL</span></label>\n      </div>\n      <div class=\"checks\" style=\"margin-top:8px\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"amp_integral\"><span>Aplicar a ampola inteira, sem fracionar (evita descarte e erro de aspiração)</span></label>\n      </div>\n      <p style=\"font-size:12px;color:var(--slate);margin:9px 0 0\">A RENAME 2024 (Componente Básico) lista <b>cianocobalamina 500 mcg/mL solução injetável</b>; a ampola comercial de 2 mL contém 1.000 mcg. <b>Não consta da REMUME de Betim</b> (conferido no documento do Projeto) – confirmar com a farmácia municipal. Os dois últimos itens são hidroxocobalamina, que permite intervalo de manutenção mais longo.</p>\n\n      <div class=\"grouplab\">Preferência de via, quando ambas forem possíveis</div>\n      <div class=\"radios\">\n        <label><input type=\"radio\" name=\"via\" value=\"auto\" checked><span>Decidir pelo protocolo</span></label>\n        <label><input type=\"radio\" name=\"via\" value=\"im\"><span>Forçar intramuscular</span></label>\n        <label><input type=\"radio\" name=\"via\" value=\"vo\"><span>Forçar oral</span></label>\n      </div>\n    </div>\n  </section>\n\n</form>\n\n<div id=\"out\"></div>\n\n<footer>\n  <p><b>Uso profissional.</b> Ferramenta de apoio à decisão; não substitui o julgamento clínico nem a leitura da bula vigente. Não existe PCDT do Ministério da Saúde para deficiência de vitamina B12 — as recomendações abaixo vêm de diretrizes internacionais adaptadas às apresentações disponíveis no SUS, e essa origem está sinalizada em cada bloco.</p>\n  <p class=\"noprint\">Referências: NICE NG239 — Vitamin B12 deficiency in over 16s (2024) · Devalia V, Hamilton MS, Molloy AM, BSH (2014) · Green R et al., Nat Rev Dis Primers (2017) · Carmel R, Blood (2008) · RENAME 2024 · Nota Técnica CRF-MG 020/2022.</p>\n</footer>\n</div>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst num = id => { const v = ($(id).value||'').toString().replace(',', '.').trim(); if(v==='') return null; const n = parseFloat(v); return isNaN(n)?null:n; };\nconst on = id => $(id).checked;\nconst fmt = (n,d=1) => n==null?'—':n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});\nconst esc = s => String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));\n\nfunction compute(){\n  const d = {};\n  d.sexo=$('sexo').value; d.idade=num('idade'); d.peso=num('peso');\n  d.gest=on('gestante'); d.lact=on('lactante');\n  d.b12=num('b12'); d.mma=num('mma'); d.hcy=num('hcy'); d.folato=num('folato');\n  d.hb=num('hb'); d.vcm=num('vcm'); d.rdw=num('rdw'); d.plaq=num('plaq');\n  d.neut=num('neut'); d.retic=num('retic'); d.ldh=num('ldh'); d.bi=num('bi');\n  d.k=num('k'); d.cr=num('cr'); d.ferritina=num('ferritina'); d.tsh=num('tsh');\n  d.crianca = d.idade!=null && d.idade<12;\n  d.menor16 = d.idade!=null && d.idade<16;\n\n  d.neuro = [...document.querySelectorAll('.neuro:checked')].length>0;\n  d.malabs = [...document.querySelectorAll('.mala:checked')].map(e=>e.dataset.txt);\n  d.reversivel = on('c_vegan')||on('c_metf')||on('c_ibp')||on('c_etil')||on('c_n2o')||on('c_desnut');\n  d.supl = on('f_supl');\n  d.elevaFalso = on('f_hepato')||on('f_mielo');\n\n  /* --- anemia --- */\n  const corte = d.gest?11:(d.sexo==='M'?(d.idade!=null&&d.idade>=60?12.7:13):(d.idade!=null&&d.idade>=60?11.5:12));\n  d.corte=corte;\n  d.anemia = d.hb!=null ? d.hb<corte : null;\n  d.macro = d.vcm!=null && d.vcm>100;\n  d.macroGrave = d.vcm!=null && d.vcm>110;\n  d.pancito = (d.hb!=null&&d.anemia) && (d.plaq!=null&&d.plaq<150) && (d.neut!=null&&d.neut<1.8);\n  d.hemoInt = (d.ldh!=null&&d.ldh>500) || (d.bi!=null&&d.bi>1.2);\n  d.ferroAssoc = d.ferritina!=null && d.ferritina<30;\n\n  /* --- estado da B12 --- */\n  let st='indef', label='Estadiamento incompleto', desc='', cid='';\n  const B=d.b12;\n  const mmaAlto = d.mma!=null && d.mma>0.40;\n  const hcyAlto = d.hcy!=null && d.hcy>15;\n  const drc = d.cr!=null && d.cr>1.5;\n  d.mmaAlto=mmaAlto; d.hcyAlto=hcyAlto; d.drc=drc;\n\n  if(B!=null){\n    if(B<200) st='deficiente';\n    else if(B<300) st = (mmaAlto||hcyAlto) ? 'deficiente' : 'indeterminado';\n    else st = (mmaAlto && hcyAlto) ? 'funcional' : 'suficiente';\n  } else if(mmaAlto||hcyAlto){ st='deficiente'; }\n\n  /* deficiência de folato isolada: Hcy alta com MMA normal */\n  d.folatoBaixo = d.folato!=null && d.folato<4;\n  if(hcyAlto && d.mma!=null && !mmaAlto && st!=='deficiente') st='folato';\n  if(d.folatoBaixo && st==='suficiente') st='folato';\n\n  if(st==='deficiente'){ label='Deficiência de vitamina B12'; cid='E53.8 · D51.9 se houver anemia'; desc='Cobalamina abaixo do limiar ou marcadores metabólicos alterados. Tratar agora e investigar a causa em paralelo — não esperar o resultado etiológico para iniciar.'; }\n  else if(st==='indeterminado'){ label='Zona indeterminada de cobalamina'; cid='—'; desc='B12 entre 200 e 300 pg/mL é a faixa cinzenta: nem confirma nem exclui. A definição vem do ácido metilmalônico e da homocisteína, ou do quadro clínico quando os metabólitos não estiverem disponíveis.'; }\n  else if(st==='funcional'){ label='Deficiência funcional de cobalamina'; cid='E53.8'; desc='B12 sérica normal com ácido metilmalônico e homocisteína elevados. A dosagem sérica mede a cobalamina ligada à haptocorrina, biologicamente inerte; o defeito está na fração ativa.'; }\n  else if(st==='folato'){ label='Padrão sugestivo de deficiência de folato'; cid='E53.8 · D52.9'; desc='Homocisteína elevada com ácido metilmalônico normal aponta folato, não cobalamina. Confirmar a B12 antes de repor folato isoladamente.'; }\n  else if(st==='suficiente'){ label='Sem deficiência de B12'; cid='—'; desc='Cobalamina adequada. Se a suspeita clínica for forte, reveja os confundidores antes de descartar.'; }\n  else { label='Estadiamento incompleto'; cid='—'; desc='Informe a B12 sérica ou, na indisponibilidade dela, ácido metilmalônico e homocisteína.'; }\n\n  d.st=st; d.label=label; d.cid=cid; d.desc=desc;\n  d.tratar = ['deficiente','funcional'].includes(st) || (st==='indeterminado' && (d.neuro || d.macro || d.anemia===true));\n\n  /* --- via --- */\n  const pref = document.querySelector('input[name=via]:checked').value;\n  let via, motivo;\n  if(d.neuro){ via='IM'; motivo='envolvimento neurológico'; }\n  else if(d.malabs.length){ via='IM'; motivo='má absorção estabelecida: '+d.malabs.join('; '); }\n  else if(d.anemia===true && d.hb!=null && d.hb<8){ via='IM'; motivo='anemia grave, com necessidade de resposta rápida'; }\n  else { via='VO'; motivo='ausência de má absorção e de acometimento neurológico'; }\n  if(pref==='im'){ via='IM'; motivo=motivo+' — via forçada manualmente'; }\n  if(pref==='vo' && !d.neuro){ via='VO'; motivo=motivo+' — via forçada manualmente'; }\n  if(pref==='vo' && d.neuro){ via='IM'; motivo='envolvimento neurológico: a via oral não é aceita como tratamento inicial, mesmo por preferência'; }\n  d.via=via; d.motivo=motivo;\n  d.permanente = on('c_pa')||on('c_gastrec')||on('c_bar')||on('c_ileo');\n\n  /* --- risco de hipocalemia --- */\n  d.apres = document.querySelector('input[name=apres]:checked').value;\n  d.integral = on('amp_integral');\n  d.riscoK = (d.hb!=null && d.hb<8) || d.macroGrave || d.pancito;\n  d.kBaixo = d.k!=null && d.k<3.5;\n  return d;\n}\n\nconst APRES = {\n  amicored500:{nome:'AMICORED 500 mcg/mL (cianocobalamina) — VMG Farmacêutica',\n    emb:'Ampola de 2 mL contendo 1.000 mcg. Cartucho com 1, 2 ou 50 ampolas.',\n    sal:'ciano', mcgAmp:1000, mlAmp:2, rename:true},\n  amicored2500:{nome:'AMICORED 2.500 mcg/mL (cianocobalamina) — VMG Farmacêutica',\n    emb:'Ampola de 2 mL contendo 5.000 mcg. Cartucho com 1, 2 ou 50 ampolas.',\n    sal:'ciano', mcgAmp:5000, mlAmp:2},\n  biolab:{nome:'VITAMINA B12 2.000 mcg/mL (cianocobalamina) — Biolab',\n    emb:'Ampola de 2,5 mL contendo 5.000 mcg. Cartucho com 2 ampolas.',\n    sal:'ciano', mcgAmp:5000, mlAmp:2.5},\n  bedoze:{nome:'BEDOZE 5 mg/mL (cloridrato de hidroxocobalamina) — Eurofarma',\n    emb:'Ampola de 1 mL contendo 5.000 mcg. Cartucho com 2 ou 6 ampolas. Uso adulto e pediátrico.',\n    sal:'hidroxo', mcgAmp:5000, mlAmp:1, lactacao:true},\n  rubranova:{nome:'RUBRANOVA 5.000 mcg/2 mL (cloridrato de hidroxocobalamina)',\n    emb:'Ampola de 2 mL contendo 5.000 mcg. Também existe apresentação de 15.000 mcg/2 mL.',\n    sal:'hidroxo', mcgAmp:5000, mlAmp:2}\n};\n\nfunction volume(a, mcg){\n  const ml = mcg/(a.mcgAmp/a.mlAmp);\n  return ml.toLocaleString('pt-BR',{minimumFractionDigits:ml<1?1:0, maximumFractionDigits:2});\n}\n\nfunction prescricao(d){\n  const L=[];\n  const a = APRES[d.apres];\n  if(d.via==='IM'){\n    const inteiro = a.mcgAmp===1000;\n    const doseMcg = inteiro ? 1000 : (d.integral ? a.mcgAmp : 1000);\n    const desc = inteiro ? '1 ampola (1.000 mcg)'\n      : (d.integral ? `1 ampola inteira (${a.mcgAmp.toLocaleString('pt-BR')} mcg)`\n                    : `${volume(a,1000)} mL da ampola (1.000 mcg)`);\n    L.push(a.nome);\n    L.push(a.emb);\n    if(a.rename) L.push('Corresponde ao item da RENAME 2024: cianocobalamina 500 mcg/mL solução injetável (Componente Básico). Não listada na REMUME de Betim – confirmar disponibilidade.');\n    L.push('');\n    if(d.neuro){\n      L.push('FASE DE ATAQUE (com acometimento neurológico)');\n      L.push(`Aplicar ${desc} por via intramuscular profunda, em dias alternados,`);\n      L.push('até que não haja mais melhora neurológica — reavaliar semanalmente, por até 3 semanas.');\n      L.push(`Quantidade estimada para 3 semanas: ${inteiro||d.integral ? '11 ampolas' : '3 ampolas (fracionadas)'}.`);\n    } else {\n      L.push('FASE DE ATAQUE (sem acometimento neurológico)');\n      L.push(`Aplicar ${desc} por via intramuscular profunda, três vezes por semana,`);\n      L.push('durante 2 semanas (segunda, quarta e sexta-feira).');\n      L.push(`Quantidade para o ataque: ${inteiro||d.integral ? '6 ampolas' : '2 ampolas (fracionadas)'}.`);\n    }\n    L.push('');\n    L.push('MANUTENÇÃO');\n    const intervalo = a.sal==='hidroxo' ? (d.neuro ? 'a cada 2 meses' : 'a cada 3 meses') : 'uma vez por mês';\n    if(d.permanente){\n      L.push(`Aplicar ${desc} por via intramuscular, ${intervalo}, por tempo indeterminado.`);\n      L.push('A causa identificada é irreversível: a reposição é vitalícia e sua suspensão leva à recidiva,');\n      L.push('com risco de dano neurológico permanente.');\n    } else {\n      L.push(`Aplicar ${desc} por via intramuscular, ${intervalo},`);\n      L.push('até a correção da causa de base e a normalização clínica e laboratorial.');\n      L.push('Reavaliar a necessidade de manutenção em 3 a 6 meses.');\n    }\n    L.push('');\n    if(a.sal==='hidroxo'){\n      L.push('Intervalo de manutenção: a hidroxocobalamina tem ligação proteica e retenção tecidual muito');\n      L.push('superiores às da cianocobalamina, o que permite o espaçamento de 2 a 3 meses preconizado');\n      L.push('pelas diretrizes britânicas. Perde-se menos vitamina na urina após cada aplicação.');\n    } else {\n      L.push('Intervalo de manutenção: as diretrizes britânicas preconizam 2 a 3 meses, mas o fármaco');\n      L.push('daquelas recomendações é a hidroxocobalamina. A cianocobalamina tem excreção urinária');\n      L.push('mais rápida, e por isso o intervalo mensal é o adequado para este sal.');\n    }\n    if(!inteiro && !d.integral){\n      L.push('');\n      L.push(`Fracionamento: aspirar ${volume(a,1000)} mL da ampola de ${a.mlAmp.toLocaleString('pt-BR')} mL.`);\n      L.push('As ampolas não são multidose — descartar o volume restante após o preparo.');\n      L.push('Se o fracionamento for inviável na rotina da sala de procedimentos, marque a opção de');\n      L.push('ampola inteira: doses de 1.000 a 5.000 mcg são igualmente seguras, apenas menos econômicas.');\n    }\n  } else {\n    L.push('VITAMINA B12 ORAL EM ALTA DOSE');\n    L.push('');\n    L.push('Opções comerciais equivalentes para este fim:');\n    L.push('  - Cianocobalamina 1.000 mcg ou 5.000 mcg — comprimido ou cápsula');\n    L.push('  - Mecobe 1.000 mcg (mecobalamina) — comprimido sublingual, Myralis');\n    L.push('');\n    L.push('Tomar 1.000 a 2.000 mcg por via oral, uma vez ao dia, em jejum,');\n    L.push('de forma contínua enquanto persistir a causa.');\n    L.push('Duração mínima: 3 meses, com reavaliação clínica e de hemograma.');\n    L.push('');\n    L.push('Base da dose: doses orais elevadas são absorvidas por difusão passiva, independente do fator');\n    L.push('intrínseco — cerca de 1% da dose ingerida. Por isso 1.000 a 2.000 mcg/dia repõem mesmo sem');\n    L.push('a via ativa do íleo, e não apenas nas causas dietéticas.');\n  }\n  return L;\n}\n\nfunction render(){\n  const d = compute();\n  const o = $('out');\n  if(d.b12==null && d.mma==null && d.hcy==null){\n    o.innerHTML = `<div class=\"empty\"><b>Aguardando os exames</b>Informe a vitamina B12 sérica. Se ela já estiver na zona indeterminada, acrescente ácido metilmalônico e homocisteína.</div>`;\n    return;\n  }\n  let h='';\n  const row=(a,b,c)=>`<tr><td>${a}</td><td class=\"num\">${b}</td><td>${c}</td></tr>`;\n\n  h += `<div class=\"verdict\"><p class=\"vlab\">Conclusão diagnóstica</p><h2>${esc(d.label)}</h2><p>${esc(d.desc)}</p>${d.cid&&d.cid!=='—'?`<span class=\"cid\">CID-10 · ${esc(d.cid)}</span>`:''}</div>`;\n\n  /* régua de limiares */\n  const segs=[['Deficiência','B12 &lt; 200 pg/mL'],['Zona indeterminada','200 a 300 pg/mL'],['Provavelmente suficiente','&gt; 300 pg/mL']];\n  let pos=-1;\n  if(d.b12!=null) pos = d.b12<200?0:(d.b12<300?1:2);\n  h += `<div class=\"ruler\"><h3>Limiares de cobalamina sérica</h3><div class=\"track\">`;\n  segs.forEach((s,i)=>{ h += `<div class=\"seg ${i===pos?'here on':''}\"><div class=\"segbar\"></div></div>`; });\n  h += `</div><div class=\"track\" style=\"gap:3px\">`;\n  segs.forEach((s,i)=>{ h += `<div class=\"seg ${i===pos?'here':''}\"><div class=\"segtxt\"><b>${s[0]}</b><br>${s[1]}</div></div>`; });\n  h += `</div><p class=\"rulernote\">A B12 sérica mede a cobalamina total, e cerca de 80% dela circula ligada à haptocorrina, sem disponibilidade tecidual. Por isso o valor sérico erra nos dois sentidos e a clínica pesa mais que o número.</p></div>`;\n\n  /* índices */\n  h += `<div class=\"card\"><h3>Leitura dos exames</h3><div class=\"inner\"><table><thead><tr><th>Parâmetro</th><th>Valor</th><th>Leitura</th></tr></thead><tbody>`;\n  if(d.b12!=null) h += row('B12 sérica', fmt(d.b12,0)+' pg/mL', d.b12<200?'<span class=\"tagbad\">Abaixo do limiar de deficiência</span>':(d.b12<300?'<span class=\"tagmid\">Zona indeterminada — exige metabólitos</span>':'<span class=\"tagok\">Acima do limiar</span>'));\n  if(d.mma!=null) h += row('Ácido metilmalônico', fmt(d.mma,2)+' µmol/L', d.mmaAlto?(d.drc?'<span class=\"tagmid\">Elevado, mas há disfunção renal — pode ser falso-positivo</span>':'<span class=\"tagbad\">Elevado — específico de deficiência de cobalamina</span>'):'<span class=\"tagok\">Normal</span>');\n  if(d.hcy!=null) h += row('Homocisteína', fmt(d.hcy,1)+' µmol/L', d.hcyAlto?'<span class=\"tagbad\">Elevada — sobe na carência de B12, de folato e de B6</span>':'<span class=\"tagok\">Normal</span>');\n  if(d.folato!=null) h += row('Folato sérico', fmt(d.folato,1)+' ng/mL', d.folatoBaixo?'<span class=\"tagbad\">Baixo — repor apenas depois de garantida a cobalamina</span>':'<span class=\"tagok\">Adequado</span>');\n  if(d.vcm!=null) h += row('VCM', fmt(d.vcm,1)+' fL', d.macroGrave?'<span class=\"tagbad\">Macrocitose acentuada — típica de megaloblastose</span>':(d.macro?'<span class=\"tagmid\">Macrocitose</span>':(d.ferroAssoc?'<span class=\"tagmid\">VCM normal com ferropenia associada mascara a macrocitose</span>':'<span class=\"tagok\">Normal — presente em até um terço dos deficientes</span>')));\n  if(d.hb!=null) h += row('Hemoglobina', fmt(d.hb,1)+' g/dL', d.anemia?'<span class=\"tagbad\">Anemia (corte '+fmt(d.corte,1)+' g/dL)</span>':'<span class=\"tagok\">Sem anemia</span>');\n  if(d.plaq!=null||d.neut!=null) h += row('Plaquetas e neutrófilos', (d.plaq!=null?fmt(d.plaq,0)+' / ':'— / ')+(d.neut!=null?fmt(d.neut,1):'—'), d.pancito?'<span class=\"tagbad\">Pancitopenia — megaloblastose avançada</span>':'<span class=\"tagok\">Sem citopenia associada</span>');\n  if(d.ldh!=null||d.bi!=null) h += row('LDH e bilirrubina indireta', (d.ldh!=null?fmt(d.ldh,0)+' / ':'— / ')+(d.bi!=null?fmt(d.bi,2):'—'), d.hemoInt?'<span class=\"tagmid\">Padrão de eritropoiese ineficaz — pode simular hemólise</span>':'<span class=\"tagok\">Sem marcadores de destruição intramedular</span>');\n  if(d.ferritina!=null) h += row('Ferritina', fmt(d.ferritina,0)+' ng/mL', d.ferroAssoc?'<span class=\"tagbad\">Ferropenia associada — tratar as duas carências</span>':'<span class=\"tagok\">Estoques de ferro preservados</span>');\n  if(d.k!=null) h += row('Potássio', fmt(d.k,1)+' mEq/L', d.kBaixo?'<span class=\"tagbad\">Hipocalemia antes de tratar — corrigir primeiro</span>':'<span class=\"tagok\">Normal</span>');\n  h += `</tbody></table></div></div>`;\n\n  /* alertas */\n  let flags='';\n  if(d.neuro) flags += `<div class=\"flag stop\"><span class=\"ic\">!</span><div><b>Acometimento neurológico — trate hoje</b>A degeneração combinada subaguda acomete os cordões posteriores e laterais e pode se tornar <b>irreversível</b> se o tratamento for adiado. Não aguarde anti-fator intrínseco, endoscopia ou metabólitos: inicie a cianocobalamina e investigue em paralelo. A ausência de anemia ou de macrocitose não afasta o diagnóstico — o quadro neurológico ocorre com hemograma normal em parcela relevante dos casos.</div></div>`;\n  if(d.riscoK) flags += `<div class=\"flag stop\"><span class=\"ic\">!</span><div><b>Risco de hipocalemia nas primeiras 48 horas</b>A resposta hematopoiética à reposição consome potássio rapidamente pela incorporação celular maciça, podendo precipitar arritmia. Dose o potássio antes de iniciar, repita em 48 a 72 horas e corrija preventivamente se estiver no limite inferior. O risco é maior justamente nos quadros mais graves — anemia intensa, macrocitose acentuada e pancitopenia.</div></div>`;\n  if(d.kBaixo) flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Hipocalemia já presente</b>Corrija o potássio antes ou simultaneamente à primeira dose, e monitore de perto nas primeiras 72 horas.</div></div>`;\n  if(d.folatoBaixo && d.tratar) flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Nunca reponha folato isoladamente</b>O folato corrige a anemia megaloblástica e mascara o quadro hematológico, mas <b>não impede — e pode acelerar — a progressão do dano neurológico</b>. Inicie a cobalamina primeiro e só então associe o ácido fólico.</div></div>`;\n  if(d.lact && d.tratar && d.via==='IM' && d.apres==='bedoze') flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Bedoze e amamentação</b>A bula do Bedoze contraindica o uso durante a lactação por ausência de dados de segurança — restrição formal do fabricante, não um risco demonstrado. Se a paciente amamenta, prefira uma apresentação de cianocobalamina, cuja bula não traz essa restrição.</div></div>`;\n  if(d.supl) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Paciente já em uso de B12</b>A dosagem sérica após o início do tratamento não é interpretável e não deve ser repetida para avaliar resposta. Guie-se pelo hemograma e pela evolução clínica.</div></div>`;\n  if(d.elevaFalso) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>B12 sérica falsamente elevada</b>Hepatopatia e síndromes mieloproliferativas aumentam a haptocorrina circulante e elevam a cobalamina total sem que haja disponibilidade tecidual. Nesse contexto, um valor normal não exclui deficiência — decida por ácido metilmalônico e homocisteína.</div></div>`;\n  if(d.drc && d.mmaAlto) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Metilmalônico elevado com disfunção renal</b>A depuração reduzida eleva o ácido metilmalônico independentemente da cobalamina. Interprete junto com a homocisteína e com o quadro clínico.</div></div>`;\n  if(d.ferroAssoc && d.macro===false) flags += `<div class=\"flag info\"><span class=\"ic\">i</span><div><b>Carências combinadas</b>Ferropenia concomitante normaliza o VCM e pode apagar a macrocitose. O RDW elevado com VCM normal é a pista. Trate as duas deficiências.</div></div>`;\n  if(d.tsh!=null && d.tsh>10) flags += `<div class=\"flag info\"><span class=\"ic\">i</span><div><b>TSH elevado</b>Hipotireoidismo é causa independente de macrocitose e acompanha a anemia perniciosa na poliautoimunidade. Investigue as duas linhas.</div></div>`;\n  if(d.hb!=null && d.hb<7) flags += `<div class=\"flag stop\"><span class=\"ic\">!</span><div><b>Hemoglobina abaixo de 7 g/dL</b>Avalie transfusão apenas se houver sintomas isquêmicos ou instabilidade — a anemia megaloblástica costuma ser de instalação lenta e bem tolerada, e a resposta à cobalamina é rápida. Transfundir com cautela pelo risco de sobrecarga volêmica.</div></div>`;\n  if(d.tratar && d.via==='IM') flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Não use associações de complexo B para repor cobalamina</b>Citoneurin, Citoneurim, Cronobê Complex, Nevrix e Dolo-Neurobion combinam a B12 com <b>piridoxina 100 mg e tiamina 100 mg</b> por ampola. São indicadas como coadjuvantes analgésicos em dor lombar e neuropatia, em ciclos curtos — não para reposição prolongada. A piridoxina em 100 mg por aplicação, repetida ao longo de meses, causa <b>neuropatia sensitiva por toxicidade de B6</b>, cujo quadro é indistinguível da própria neuropatia que se pretende tratar. Prescreva a cobalamina isolada.</div></div>`;\n  if(flags) h += flags;\n\n  /* prescrição */\n  if(!d.tratar){\n    if(d.st==='indeterminado'){\n      h += `<div class=\"card\"><h3>Defina antes de tratar</h3><div class=\"inner\"><p>B12 entre 200 e 300 pg/mL sem sintomas neurológicos, sem anemia e sem macrocitose não autoriza nem exclui o tratamento. Peça <b>ácido metilmalônico</b> — o marcador específico de cobalamina — e <b>homocisteína</b>.</p><p>Se os metabólitos não estiverem acessíveis na rede, existe uma saída pragmática: <b>teste terapêutico</b> com cianocobalamina por 4 a 8 semanas, documentando antes e depois o hemograma, o VCM e os sintomas. A resposta confirma retrospectivamente o diagnóstico. Registre a estratégia no prontuário.</p></div></div>`;\n    } else if(d.st==='folato'){\n      h += `<div class=\"card\"><h3>Conduta: repor folato, não cobalamina</h3><div class=\"inner\"><p>O padrão metabólico aponta carência de folato. Antes de prescrever, <b>confirme que a B12 está adequada</b> — repor folato com cobalamina baixa mascara a anemia e permite a progressão neurológica silenciosa.</p><pre class=\"rx\">ÁCIDO FÓLICO 5 mg — comprimido (CBAF, disponível na UBS)\nTomar 1 comprimido por via oral, uma vez ao dia, por 4 meses.\nProrrogar enquanto persistir a causa (má absorção, etilismo, gestação,\nhemólise crônica, metotrexato, fenitoína).</pre></div></div>`;\n    } else {\n      h += `<div class=\"card\"><h3>Sem indicação de reposição</h3><div class=\"inner\"><p>Os parâmetros não caracterizam deficiência de cobalamina. Se a suspeita clínica for forte apesar do resultado, reveja os confundidores da seção 04 e considere ácido metilmalônico antes de descartar.</p></div></div>`;\n    }\n  } else {\n    h += `<div class=\"card route ${d.via==='IM'?'im':'oral'}\"><h3>${d.via==='IM'?'Via intramuscular':'Via oral'}</h3><div class=\"inner\">`;\n    h += `<p><b>Critério que definiu a via:</b> ${esc(d.motivo)}.</p>`;\n    h += `<pre class=\"rx\">${prescricao(d).map(esc).join('\\n')}</pre>`;\n    if(d.folatoBaixo) h += `<pre class=\"rx\">ASSOCIAR, a partir da segunda dose de cianocobalamina:\nÁCIDO FÓLICO 5 mg — comprimido\nTomar 1 comprimido por via oral, uma vez ao dia, por 4 meses.</pre>`;\n    if(d.ferroAssoc) h += `<pre class=\"rx\">ASSOCIAR, por ferropenia concomitante:\nSULFATO FERROSO 40 mg de ferro elementar — comprimido\nTomar 3 comprimidos por via oral, em dose única diária, 1 hora antes do café da manhã.\nDuração: 3 a 6 meses, até ferritina maior ou igual a 30 ng/mL.</pre>`;\n    h += `<button class=\"btn\" type=\"button\" onclick=\"copiar()\">Copiar prescrição</button></div></div>`;\n\n    /* monitoramento */\n    h += `<div class=\"card\"><h3>Monitoramento</h3><div class=\"inner\"><table><thead><tr><th>Momento</th><th>O que avaliar</th><th>Resposta esperada</th></tr></thead><tbody>`;\n    h += row('48 a 72 horas','Potássio sérico','Queda por incorporação celular durante a resposta hematopoiética — corrigir se necessário');\n    h += row('7 a 10 dias','Reticulócitos','Pico de reticulocitose. Ausência de resposta obriga a rever o diagnóstico ou procurar carência associada de ferro ou folato');\n    h += row('8 semanas','Hemograma completo','Normalização de Hb e VCM; a plaquetopenia e a neutropenia corrigem antes da anemia');\n    h += row('Semanas a meses','Sintomas neurológicos','Melhora progressiva, mais lenta que a hematológica. O déficit residual após 6 a 12 meses tende a ser definitivo');\n    h += row('3 a 6 meses','Ferritina','Ferropenia pode se manifestar depois, quando a eritropoiese acelerada consome os estoques');\n    h += row('Não repetir','B12 sérica','Após iniciar a reposição a dosagem perde valor — não use para avaliar resposta nem para ajustar dose');\n    h += `</tbody></table></div></div>`;\n\n    /* investigação */\n    let inv=[];\n    if(!d.malabs.length && !d.reversivel) inv.push('<b>Nenhuma causa foi marcada.</b> Deficiência de B12 sem causa aparente exige investigação ativa — a carência puramente dietética é incomum fora do vegetarianismo estrito, porque as reservas hepáticas duram de 3 a 5 anos.');\n    inv.push('<b>Anticorpo anti-fator intrínseco:</b> muito específico, mas sensibilidade em torno de 50% — negativo não exclui anemia perniciosa. O anti-célula parietal é o oposto: sensível e pouco específico.');\n    if(on('c_pa')||on('antifi')) inv.push('<b>Anemia perniciosa confirmada ou provável:</b> encaminhe para endoscopia digestiva alta com biópsia. A gastrite atrófica corpo-fúndica associa-se a risco aumentado de adenocarcinoma gástrico e de tumor neuroendócrino, e o seguimento endoscópico é conduta estabelecida.');\n    inv.push('Rastrear poliautoimunidade: tireoidite de Hashimoto (TSH e anti-TPO), diabetes tipo 1, vitiligo e doença celíaca acompanham a anemia perniciosa com frequência.');\n    if(on('c_metf')) inv.push('<b>Metformina:</b> reduz a absorção ileal de forma dose e tempo dependente. Não é motivo para suspender o antidiabético — reponha a B12 e mantenha a metformina, com dosagem anual.');\n    if(on('c_ibp')) inv.push('<b>Inibidor de bomba de prótons:</b> a hipocloridria impede a liberação da cobalamina ligada às proteínas do alimento. Reavalie se a indicação do IBP persiste; a suplementação oral funciona mesmo com o IBP mantido.');\n    if(on('c_bar')||on('c_gastrec')) inv.push('<b>Pós-cirúrgico gástrico:</b> a deficiência aparece tipicamente 2 a 5 anos após o procedimento, quando as reservas hepáticas se esgotam. Rastreie anualmente B12, ferro, cálcio, vitamina D e tiamina.');\n    if(on('c_n2o')) inv.push('<b>Óxido nitroso:</b> oxida irreversivelmente o cobalto da cobalamina e pode precipitar mielopatia aguda mesmo com B12 sérica normal. A exposição recreativa é subnotificada — pergunte diretamente.');\n    if(d.gest||d.lact) inv.push('<b>Gestação e lactação:</b> a cobalamina materna determina a reserva do lactente. A deficiência no lactente de mãe vegana ou com anemia perniciosa causa atraso do desenvolvimento neuropsicomotor potencialmente grave.');\n    inv.push('Orientação alimentar: carnes, vísceras, ovos, leite e derivados. Em veganos, a suplementação é permanente e não substituível por dieta — nenhum alimento vegetal não fortificado é fonte confiável.');\n    h += `<div class=\"card\"><h3>Investigação etiológica</h3><div class=\"inner\"><ul>${inv.map(x=>`<li>${x}</li>`).join('')}</ul></div></div>`;\n\n    /* acesso */\n    let ac = `<p><b>Cianocobalamina 500 mcg/mL solução injetável está no Componente Básico da RENAME 2024</b>, mas <b>não consta da REMUME de Betim</b>: confirme com a farmácia municipal antes de prometer a dispensação; se houver, a aplicação pode ser feita na sala de procedimentos da UBS. A aplicação intramuscular pode ser feita na sala de procedimentos da unidade, o que resolve tanto o custo quanto a adesão.</p>`;\n    ac += `<div class=\"flag info\" style=\"margin:10px 0\"><span class=\"ic\">i</span><div><b>Concentração do item da RENAME</b>A RENAME 2024 descreve o item como <b>cianocobalamina 500 mcg/mL</b>; a ampola de 2 mL contém 1.000 mcg. Ao pesquisar em pregão, estoque ou tabela CMED, busque por “cianocobalamina 500 mcg/mL solução injetável”.</div></div>`;\n    ac += `<table><thead><tr><th>Produto</th><th>Sal</th><th>Ampola</th><th>Observação</th></tr></thead><tbody>\n      <tr><td>Amicored 500 mcg/mL</td><td>Cianocobalamina</td><td class=\"num\">2 mL = 1.000 mcg</td><td>Corresponde ao item da RENAME. Baixo custo — o preço máximo de venda ao governo em 2024 ficou em torno de R$ 6,71 pela caixa com 2 ampolas</td></tr>\n      <tr><td>Amicored 2.500 mcg/mL</td><td>Cianocobalamina</td><td class=\"num\">2 mL = 5.000 mcg</td><td>Útil quando só houver essa concentração; fracionar ou aplicar a ampola inteira</td></tr>\n      <tr><td>Vitamina B12 Biolab 2.000 mcg/mL</td><td>Cianocobalamina</td><td class=\"num\">2,5 mL = 5.000 mcg</td><td>Alternativa de farmácia comercial</td></tr>\n      <tr><td>Bedoze 5 mg/mL (Eurofarma)</td><td>Hidroxocobalamina</td><td class=\"num\">1 mL = 5.000 mcg</td><td>Uso adulto e pediátrico. Permite manutenção a cada 2 a 3 meses. Bula contraindica na lactação</td></tr>\n      <tr><td>Rubranova 5.000 mcg/2 mL</td><td>Hidroxocobalamina</td><td class=\"num\">2 mL = 5.000 mcg</td><td>Também há apresentação de 15.000 mcg/2 mL</td></tr>\n      </tbody></table>`;\n    ac += `<p style=\"font-size:12.5px;color:var(--slate)\">As apresentações de hidroxocobalamina não constam da RENAME: são de compra pelo paciente. A vantagem é o intervalo de manutenção mais longo, que reduz idas à unidade e melhora a adesão a longo prazo — considere quando a barreira for o comparecimento mensal, não o custo.</p>`;\n    if(d.via==='VO') ac += `<p style=\"color:var(--crimson)\"><b>Atenção ao acesso:</b> a cianocobalamina <b>oral não consta da RENAME</b>. A apresentação padronizada é apenas a injetável. Na prática, prescrever a via oral significa compra pelo paciente — de custo baixo, mas não gratuito. Se houver barreira financeira, a via intramuscular mensal na UBS é a alternativa que garante o tratamento, ainda que a oral seja tecnicamente suficiente neste caso.</p>`;\n    ac += `<p>Ácido fólico 5 mg e sulfato ferroso 40 mg também são do CBAF. Verifique a REMUME de Betim para as apresentações efetivamente padronizadas no município antes de prescrever.</p>`;\n    ac += `<p style=\"font-size:12.5px;color:var(--slate)\">Não existe PCDT do Ministério da Saúde para deficiência de vitamina B12: não há LME, nem critério nacional de inclusão, nem formulário. Isso significa liberdade de prescrição no nível básico, mas também ausência de respaldo protocolar formal — registre no prontuário a diretriz adotada e a justificativa da via escolhida.</p>`;\n    h += `<div class=\"card\"><h3>Acesso no SUS</h3><div class=\"inner\">${ac}</div></div>`;\n  }\n  o.innerHTML = h;\n}\n\nfunction copiar(){\n  const t=[...document.querySelectorAll('#out .rx')].map(e=>e.innerText).join('\\n\\n');\n  navigator.clipboard.writeText(t).then(()=>{\n    document.querySelectorAll('#out .btn').forEach(b=>{ b.textContent='Prescrição copiada'; setTimeout(()=>b.textContent='Copiar prescrição',2000); });\n  });\n}\ndocument.getElementById('f').addEventListener('input', render);\ndocument.getElementById('f').addEventListener('change', render);\nconst _tw=()=>{document.querySelectorAll('#out table').forEach(t=>{\n  if(!t.parentElement.classList.contains('tw')){\n    const w=document.createElement('div'); w.className='tw';\n    t.parentNode.insertBefore(w,t); w.appendChild(t);}});};\nnew MutationObserver(_tw).observe(document.getElementById('out'),{childList:true,subtree:true});\n\nrender();\n<\/script>\n<script>(function(){function _h(){try{parent.postMessage({embId:'b12_full',embH:document.documentElement.scrollHeight},'*')}catch(e){}}window.addEventListener('load',_h);try{new ResizeObserver(_h).observe(document.body)}catch(e){setInterval(_h,800)}document.addEventListener('input',function(){setTimeout(_h,50)});})();<\/script></body>\n</html>\n";
EMB_HTML["ferro_full"] = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Reposição de ferro — calculadora clínica SUS</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bordo:#5C1A2B;\n  --bordo-deep:#3B0F1A;\n  --bone:#F7F4EF;\n  --paper:#FFFDFA;\n  --ink:#1C1A19;\n  --slate:#585048;\n  --rule:#DDD4C7;\n  --teal:#1F5C58;\n  --brass:#9A6B12;\n  --crimson:#A3182B;\n  --ok:#1F5C58;\n  --surface2:#F2ECE3;\n  --hover:#F4EEE4;\n  --sel:#F6ECEE;\n  --track:#E7DFD3;\n  --rxbg:#FBF7F0;\n  --field:#FFFFFF;\n  --navy:#2E4A7D;\n  --onbordo:#F0DDE0;\n  --onbordo-dim:#DBB7BE;\n  --onbordo-strong:#FFFFFF;\n  --headfg:#E3D3D6;\n  --headeyebrow:#C9A9AF;\n  --stopbg:#FBEDEE; --stopbd:#E0B6BC; --stopfg:#6E1220;\n  --warnbg:#FBF3E2; --warnbd:#E2CE9E; --warnfg:#5F420A;\n  --infobg:#EAF1F0; --infobd:#AFC9C6; --infofg:#123C39;\n  box-sizing:border-box;\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:env(safe-area-inset-bottom,0px);\n}\n\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n    --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n    --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n    --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n    --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n    --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n    --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n    --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n    --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n    --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bordo:#C77A8B; --bordo-deep:#241016; --bone:#17141A; --paper:#211C20;\n  --ink:#EFE8E2; --slate:#B3A69F; --rule:#3B3136;\n  --teal:#7FBDB6; --brass:#D9AE62; --crimson:#E8899A; --ok:#7FBDB6;\n  --surface2:#2A2329; --hover:#2E262C; --sel:#3A2028; --track:#3B3136;\n  --rxbg:#1D191D; --field:#1B1719; --navy:#8FAFD9;\n  --onbordo:#2A1016; --onbordo-dim:#5C2231; --onbordo-strong:#1A0A0E;\n  --headfg:#E3D3D6; --headeyebrow:#C9A9AF;\n  --stopbg:#3A1E22; --stopbd:#7A3B45; --stopfg:#F4C4CB;\n  --warnbg:#332A17; --warnbd:#705C2C; --warnfg:#EBD49A;\n  --infobg:#172B2A; --infobd:#3D6663; --infofg:#B9DCD8;\n}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\n.tw{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:0 0 10px}\n.tw table{margin:0;min-width:100%}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  background:var(--bone);\n  color:var(--ink);\n  font-family:\"Public Sans\",system-ui,sans-serif;\n  font-size:15px;\n  line-height:1.5;\n  -webkit-font-smoothing:antialiased;\n}\n.wrap{max-width:860px;margin:0 auto;padding:0 16px 80px}\n\n/* ---------- header ---------- */\nheader{\n  background:var(--bordo-deep);\n  color:var(--bone);\n  padding:26px 0 22px;\n  margin-bottom:22px;\n  border-bottom:4px solid var(--bordo);\n}\nheader .wrap{padding-bottom:0}\n.eyebrow{\n  font-family:\"IBM Plex Mono\",monospace;\n  font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;\n  color:var(--headeyebrow);margin:0 0 8px;\n}\nh1{\n  font-family:\"Fraunces\",serif;\n  font-weight:600;font-size:clamp(26px,6vw,38px);\n  line-height:1.05;margin:0 0 10px;letter-spacing:-.01em;\n}\n.sub{margin:0;font-size:13.5px;color:var(--headfg);max-width:62ch}\n.sub b{color:var(--onbordo-strong);font-weight:600}\n\n/* ---------- sections ---------- */\nsection{\n  background:var(--paper);\n  border:1px solid var(--rule);\n  border-radius:3px;\n  margin-bottom:14px;\n  overflow:hidden;\n}\n.shead{\n  display:flex;align-items:baseline;gap:10px;\n  padding:11px 14px;border-bottom:1px solid var(--rule);\n  background:var(--surface2);\n}\n.snum{\n  font-family:\"IBM Plex Mono\",monospace;font-size:11px;font-weight:600;\n  color:var(--bordo);letter-spacing:.08em;\n}\n.stitle{font-family:\"Fraunces\",serif;font-weight:600;font-size:17px;letter-spacing:-.01em}\n.sbody{padding:14px}\n\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:10px 12px}\nlabel{display:block}\n.lab{\n  display:block;font-size:11px;font-weight:600;letter-spacing:.04em;\n  text-transform:uppercase;color:var(--slate);margin-bottom:3px;\n}\n.unit{font-weight:400;text-transform:none;letter-spacing:0;color:#8B8177}\ninput[type=number],input[type=text],select{\n  width:100%;padding:8px 9px;border:1px solid var(--rule);border-radius:2px;\n  background:var(--field);color:var(--ink);\n  font-family:\"IBM Plex Mono\",monospace;font-size:15px;\n}\ninput:focus,select:focus{outline:2px solid var(--bordo);outline-offset:0;border-color:var(--bordo)}\nselect{font-family:\"Public Sans\",sans-serif}\n\n.checks{display:grid;grid-template-columns:1fr;gap:2px}\n@media(min-width:640px){.checks{grid-template-columns:1fr 1fr;gap:2px 16px}}\n.chk{display:flex;gap:8px;align-items:flex-start;padding:5px 4px;border-radius:2px;cursor:pointer;font-size:13.5px;line-height:1.35}\n.chk:hover{background:var(--hover)}\n.chk input{margin:2px 0 0;accent-color:var(--bordo);width:16px;height:16px;flex:0 0 auto}\n.grouplab{\n  font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.12em;\n  text-transform:uppercase;color:var(--bordo);margin:14px 0 6px;\n  padding-bottom:4px;border-bottom:1px dotted var(--rule);\n}\n.grouplab:first-child{margin-top:0}\n\n.radios{display:flex;flex-wrap:wrap;gap:8px}\n.radios label{\n  border:1px solid var(--rule);border-radius:2px;padding:7px 11px;cursor:pointer;\n  font-size:13px;background:var(--field);display:flex;gap:7px;align-items:center;\n}\n.radios input{accent-color:var(--bordo)}\n.radios label:has(input:checked){border-color:var(--bordo);background:var(--sel);font-weight:600}\n\n/* ---------- result ---------- */\n#out{margin-top:26px}\n.verdict{\n  background:var(--bordo);color:#fff;border-radius:3px;padding:16px 16px 14px;margin-bottom:12px;\n}\n.verdict .vlab{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--onbordo-dim);margin-bottom:5px}\n.verdict h2{font-family:\"Fraunces\",serif;font-weight:600;font-size:23px;margin:0 0 6px;line-height:1.12}\n.verdict p{margin:0;font-size:13.5px;color:var(--onbordo)}\n.cid{\n  display:inline-block;margin-top:9px;font-family:\"IBM Plex Mono\",monospace;font-size:12px;\n  background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);\n  padding:3px 8px;border-radius:2px;\n}\n\n/* signature: staging ruler */\n.ruler{margin:0 0 14px;background:var(--paper);border:1px solid var(--rule);border-radius:3px;padding:14px}\n.ruler h3{font-family:\"IBM Plex Mono\",monospace;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--bordo);margin:0 0 12px;font-weight:600}\n.track{display:flex;gap:3px;margin-bottom:8px}\n.seg{flex:1;position:relative}\n.segbar{height:9px;background:var(--track);border-radius:1px}\n.seg.on .segbar{background:var(--bordo)}\n.seg.here .segbar{background:var(--bordo);box-shadow:0 0 0 2px var(--paper),0 0 0 4px var(--bordo)}\n.segtxt{font-size:10.5px;line-height:1.25;color:var(--slate);margin-top:7px;padding-right:6px}\n.seg.here .segtxt{color:var(--bordo);font-weight:700}\n.rulernote{font-size:12px;color:var(--slate);margin:10px 0 0;padding-top:9px;border-top:1px dotted var(--rule)}\n\n.card{background:var(--paper);border:1px solid var(--rule);border-radius:3px;margin-bottom:12px}\n.card h3{\n  margin:0;padding:10px 14px;border-bottom:1px solid var(--rule);background:var(--surface2);\n  font-family:\"Fraunces\",serif;font-weight:600;font-size:16px;\n}\n.card .inner{padding:13px 14px}\n.card p{margin:0 0 9px}\n.card p:last-child{margin-bottom:0}\n.card ul{margin:0 0 9px;padding-left:19px}\n.card li{margin-bottom:5px}\n\n.route{border-left:4px solid var(--teal)}\n.route h3{color:var(--teal)}\n.route.oral{border-left-color:var(--bordo)}\n.route.oral h3{color:var(--bordo)}\n\n.rx{\n  font-family:\"IBM Plex Mono\",monospace;font-size:12.5px;line-height:1.65;\n  white-space:pre-wrap;background:var(--rxbg);border:1px solid var(--rule);\n  padding:12px;border-radius:2px;margin:0;overflow-x:auto;\n}\n.btn{\n  font-family:\"Public Sans\",sans-serif;font-size:13px;font-weight:600;\n  background:var(--bordo);color:#fff;border:0;border-radius:2px;\n  padding:9px 15px;cursor:pointer;margin-top:10px;\n}\n.btn:hover{background:var(--bordo-deep)}\n.btn:focus-visible{outline:2px solid var(--ink);outline-offset:2px}\n\n.flag{\n  display:flex;gap:9px;padding:10px 12px;border-radius:2px;margin-bottom:8px;font-size:13.5px;line-height:1.4;\n  border:1px solid;\n}\n.flag b{display:block;margin-bottom:2px}\n.flag.stop{background:var(--stopbg);border-color:var(--stopbd);color:var(--stopfg)}\n.flag.warn{background:var(--warnbg);border-color:var(--warnbd);color:var(--warnfg)}\n.flag.info{background:var(--infobg);border-color:var(--infobd);color:var(--infofg)}\n.flag .ic{font-family:\"IBM Plex Mono\",monospace;font-weight:600;flex:0 0 auto}\n\ntable{width:100%;border-collapse:collapse;font-size:13px;margin:0 0 10px}\nth,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--rule);vertical-align:top}\nth{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--slate);font-weight:600}\ntd.num{font-family:\"IBM Plex Mono\",monospace}\n.tagok{color:var(--ok);font-weight:600}\n.tagbad{color:var(--crimson);font-weight:600}\n.tagmid{color:var(--brass);font-weight:600}\n\n.empty{\n  text-align:center;padding:34px 18px;color:var(--slate);\n  border:1px dashed var(--rule);border-radius:3px;background:var(--paper);\n}\n.empty b{display:block;font-family:\"Fraunces\",serif;font-size:18px;color:var(--ink);margin-bottom:5px;font-weight:600}\n\nfooter{margin-top:30px;padding-top:16px;border-top:1px solid var(--rule);font-size:11.5px;color:var(--slate);line-height:1.55}\nfooter b{color:var(--ink)}\n\n@media print{\n  body{background:#fff}\n  header{background:#fff;color:#000;border-bottom:2px solid #000}\n  .eyebrow,.sub{color:#333}\n  form,.btn,footer .noprint{display:none}\n  .verdict{background:#fff;color:#000;border:2px solid #000}\n  .verdict h2,.verdict p,.verdict .vlab{color:#000}\n  section,.card,.ruler{break-inside:avoid}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"wrap\">\n    <p class=\"eyebrow\">Atenção Primária · SUS · Betim/MG</p>\n    <h1>Reposição de ferro:<br>do estadiamento à prescrição</h1>\n    <p class=\"sub\">Estadia a deficiência de ferro pelos três estágios laboratoriais, decide a via e devolve a <b>prescrição completa</b> — sulfato ferroso do CBAF ou ferro endovenoso com diluição e tempo de infusão prontos. Baseado no <b>PCDT Anemia por Deficiência de Ferro</b> (versão vigente de 2014 e minuta de atualização CP nº 98/2024) e na RENAME 2024.</p>\n  </div>\n</header>\n\n<div class=\"wrap\">\n<form id=\"f\" autocomplete=\"off\">\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">01</span><span class=\"stitle\">Paciente</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">Sexo</span>\n          <select id=\"sexo\"><option value=\"F\">Feminino</option><option value=\"M\">Masculino</option></select></label>\n        <label><span class=\"lab\">Idade <span class=\"unit\">anos</span></span>\n          <input type=\"number\" id=\"idade\" step=\"0.1\" min=\"0\" max=\"120\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Peso atual <span class=\"unit\">kg</span></span>\n          <input type=\"number\" id=\"peso\" step=\"0.1\" min=\"1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Altura <span class=\"unit\">cm</span></span>\n          <input type=\"number\" id=\"altura\" step=\"0.5\" min=\"30\" placeholder=\"—\"></label>\n      </div>\n      <div class=\"grouplab\">Situação gestacional</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"gestante\"><span>Gestante</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"lactante\"><span>Lactante</span></label>\n      </div>\n      <div class=\"grid\" style=\"margin-top:10px\">\n        <label><span class=\"lab\">Idade gestacional <span class=\"unit\">semanas</span></span>\n          <input type=\"number\" id=\"ig\" step=\"1\" min=\"1\" max=\"42\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Peso pré-gestacional <span class=\"unit\">kg</span></span>\n          <input type=\"number\" id=\"pesopre\" step=\"0.1\" min=\"1\" placeholder=\"—\"></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">02</span><span class=\"stitle\">Hemograma</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">Hb <span class=\"unit\">g/dL</span></span><input type=\"number\" id=\"hb\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Ht <span class=\"unit\">%</span></span><input type=\"number\" id=\"ht\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Hemácias <span class=\"unit\">10⁶/µL</span></span><input type=\"number\" id=\"rbc\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">VCM <span class=\"unit\">fL</span></span><input type=\"number\" id=\"vcm\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">HCM <span class=\"unit\">pg</span></span><input type=\"number\" id=\"hcm\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">CHCM <span class=\"unit\">g/dL</span></span><input type=\"number\" id=\"chcm\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">RDW <span class=\"unit\">%</span></span><input type=\"number\" id=\"rdw\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Reticulócitos <span class=\"unit\">%</span></span><input type=\"number\" id=\"retic\" step=\"0.01\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Plaquetas <span class=\"unit\">10³/µL</span></span><input type=\"number\" id=\"plaq\" step=\"1\" placeholder=\"—\"></label>\n      </div>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">03</span><span class=\"stitle\">Cinética do ferro e inflamação</span></div>\n    <div class=\"sbody\">\n      <div class=\"grid\">\n        <label><span class=\"lab\">Ferritina <span class=\"unit\">ng/mL</span></span><input type=\"number\" id=\"ferritina\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Ferro sérico <span class=\"unit\">µg/dL</span></span><input type=\"number\" id=\"ferro\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">CTLF / TIBC <span class=\"unit\">µg/dL</span></span><input type=\"number\" id=\"ctlf\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">IST <span class=\"unit\">% — se já calculado</span></span><input type=\"number\" id=\"istman\" step=\"0.1\" placeholder=\"auto\"></label>\n        <label><span class=\"lab\">PCR <span class=\"unit\">mg/L</span></span><input type=\"number\" id=\"pcr\" step=\"0.1\" placeholder=\"—\"></label>\n        <label><span class=\"lab\">Ret-He / CHr <span class=\"unit\">pg</span></span><input type=\"number\" id=\"rethe\" step=\"0.1\" placeholder=\"—\"></label>\n      </div>\n      <p style=\"font-size:12px;color:var(--slate);margin:11px 0 0\">Ret-He (Sysmex XN) e CHr (Advia) saem do próprio hemograma com reticulócitos, sem custo adicional de amostra — são os parâmetros mais úteis quando a ferritina está confundida por inflamação.</p>\n    </div>\n  </section>\n\n  <section>\n    <div class=\"shead\"><span class=\"snum\">04</span><span class=\"stitle\">Cenário clínico e contraindicações</span></div>\n    <div class=\"sbody\">\n\n      <div class=\"grouplab\">Indicações de ferro endovenoso (PCDT)</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_intol\" data-txt=\"intolerância absoluta ao ferro oral (náuseas/vômitos incoercíveis)\"><span>Intolerância absoluta ao ferro oral</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_ci\" data-txt=\"contraindicação ao ferro oral\"><span>Contraindicação ao ferro oral</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_refr\" data-txt=\"refratariedade: sem resposta após 8 semanas de ferro oral\"><span>Refratariedade após 8 semanas de VO</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_qt\" data-txt=\"quimioterapia em curso\"><span>Quimioterapia em curso</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_dii\" data-txt=\"doença inflamatória intestinal\"><span>Doença inflamatória intestinal</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_perda\" data-txt=\"perda sanguínea diária acima da capacidade absortiva intestinal (&gt;40 mg Fe/dia)\"><span>Perda &gt; capacidade absortiva (&gt;40 mg Fe/dia)</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_bar\" data-txt=\"gastrectomia ou bypass gástrico\"><span>Gastrectomia / bypass gástrico</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ind\" id=\"i_rapido\" data-txt=\"necessidade de correção rápida (pré-operatório, fim de gestação, risco de hemorragia)\"><span>Necessidade de correção rápida</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"i_drc\"><span>Doença renal crônica</span></label>\n      </div>\n\n      <div class=\"grouplab\">Contraindicações / cautelas ao ferro endovenoso</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ci\" id=\"c_hiper\" data-txt=\"hipersensibilidade prévia ou reação anafilática a ferro parenteral\"><span>Hipersensibilidade prévia a ferro parenteral</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ci\" id=\"c_infec\" data-txt=\"infecção aguda ou bacteriemia em atividade\"><span>Infecção aguda / bacteriemia</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ci\" id=\"c_hep\" data-txt=\"insuficiência hepática (ou TGP &gt; 3x LSN)\"><span>Insuficiência hepática</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" class=\"iv-ci\" id=\"c_sobre\" data-txt=\"hemocromatose ou sobrecarga de ferro conhecida\"><span>Hemocromatose / sobrecarga de ferro</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"c_atopia\"><span>Atopia grave / asma mal controlada</span></label>\n      </div>\n\n      <div class=\"grouplab\">Fatores que comprometem a via oral</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"o_intolprev\"><span>Intolerância prévia ao sulfato ferroso</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"o_ibp\"><span>Uso contínuo de IBP / antiácido</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"o_gastrite\"><span>Gastrite atrófica, H. pylori ou doença celíaca</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"o_ulcera\"><span>Doença ulcerosa péptica ativa</span></label>\n      </div>\n\n      <div class=\"grouplab\">Disponibilidade local de ferro EV</div>\n      <div class=\"checks\">\n        <label class=\"chk\"><input type=\"checkbox\" id=\"d_sac\" checked><span>Sacarato de hidróxido férrico</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"d_cmf\"><span>Carboximaltose férrica</span></label>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"d_deri\"><span>Derisomaltose férrica</span></label>\n      </div>\n\n      <div class=\"grouplab\">Regime oral</div>\n      <div class=\"radios\">\n        <label><input type=\"radio\" name=\"reg\" value=\"unica\" checked><span>Dose única diária</span></label>\n        <label><input type=\"radio\" name=\"reg\" value=\"alternado\"><span>Dias alternados</span></label>\n        <label><input type=\"radio\" name=\"reg\" value=\"pcdt\"><span>Fracionado (PCDT)</span></label>\n      </div>\n      <div class=\"grid\" style=\"margin-top:12px\">\n        <label><span class=\"lab\">Hb-alvo p/ Ganzoni <span class=\"unit\">g/dL</span></span><input type=\"number\" id=\"hbalvo\" step=\"0.1\" placeholder=\"auto\"></label>\n      </div>\n    </div>\n  </section>\n\n</form>\n\n<div id=\"out\"></div>\n\n<footer>\n  <p><b>Uso profissional.</b> Ferramenta de apoio à decisão; não substitui o julgamento clínico nem a leitura da bula vigente. Confira sempre o rótulo do lote dispensado — a relação gotas/mL das soluções orais varia entre fabricantes.</p>\n  <p class=\"noprint\">Referências normativas: PCDT Anemia por Deficiência de Ferro (Portaria SAS/MS nº 1.247/2014; minuta de atualização em Consulta Pública Conitec/SECTICS nº 98/2024) · RENAME 2024 · Portarias SECTICS/MS nº 17/2023, nº 20/2023 e nº 49/2024 · bulas Anvisa de sacarato de hidróxido férrico, carboximaltose férrica e derisomaltose férrica.</p>\n</footer>\n</div>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst num = id => { const v = ($(id).value||'').toString().replace(',', '.').trim(); if(v==='') return null; const n = parseFloat(v); return isNaN(n)?null:n; };\nconst on = id => $(id).checked;\nconst fmt = (n,d=1) => n==null?'—':n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});\nconst esc = s => String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));\n\n/* ---------- limiares ---------- */\nfunction corteHb(sexo, idade, gest){\n  if(gest) return {v:11, txt:'gestante'};\n  if(idade==null) return {v:12, txt:'padrão'};\n  if(idade < 0.5)  return {v:13.5, txt:'lactente < 6 meses'};\n  if(idade < 5)    return {v:11,   txt:'criança 6 meses–4 anos'};\n  if(idade < 12)   return {v:11.5, txt:'criança 5–11 anos'};\n  if(idade < 15)   return {v:12,   txt:'adolescente 12–14 anos'};\n  if(sexo==='F')   return idade>=60 ? {v:11.5, txt:'mulher ≥ 60 anos'} : {v:12,   txt:'mulher ≥ 15 anos'};\n  return             idade>=60 ? {v:12.7, txt:'homem ≥ 60 anos'}  : {v:13,   txt:'homem ≥ 15 anos'};\n}\n\n/* ---------- núcleo ---------- */\nfunction compute(){\n  const d = {};\n  d.sexo = $('sexo').value;\n  d.idade = num('idade');\n  d.gest = on('gestante');\n  d.lact = on('lactante');\n  d.ig = num('ig');\n  d.peso = num('peso');\n  d.pesopre = num('pesopre');\n  d.altura = num('altura');\n  d.hb = num('hb'); d.ht = num('ht'); d.rbc = num('rbc');\n  d.vcm = num('vcm'); d.hcm = num('hcm'); d.chcm = num('chcm');\n  d.rdw = num('rdw'); d.retic = num('retic'); d.plaq = num('plaq');\n  d.ferritina = num('ferritina'); d.ferro = num('ferro'); d.ctlf = num('ctlf');\n  d.pcr = num('pcr'); d.rethe = num('rethe');\n  d.crianca = d.idade!=null && d.idade < 12;\n  d.menor18 = d.idade!=null && d.idade < 18;\n\n  d.ist = num('istman');\n  d.istCalc = false;\n  if(d.ist==null && d.ferro!=null && d.ctlf!=null && d.ctlf>0){ d.ist = d.ferro/d.ctlf*100; d.istCalc = true; }\n\n  d.pesoUso = d.gest && d.pesopre!=null ? d.pesopre : d.peso;\n  d.pesoIdeal = d.altura!=null ? 25*Math.pow(d.altura/100,2) : null;\n  d.imc = (d.peso!=null && d.altura!=null) ? d.peso/Math.pow(d.altura/100,2) : null;\n\n  const c = corteHb(d.sexo, d.idade, d.gest);\n  d.corte = c;\n  d.anemia = d.hb!=null ? d.hb < c.v : null;\n\n  d.inflam = (d.pcr!=null && d.pcr>5) || on('i_dii') || on('i_qt') || on('i_drc') || on('c_infec');\n  d.vcmCorte = (d.idade==null) ? 80 : (d.idade<5 ? 72 : (d.idade<12 ? 76 : 80));\n  d.micro = d.vcm!=null && d.vcm < d.vcmCorte;\n  d.hipo  = (d.chcm!=null && d.chcm<32) || (d.hcm!=null && d.hcm<27);\n  d.anisoc = d.rdw!=null && d.rdw>14.5;\n  d.retheBaixo = d.rethe!=null && d.rethe<29;\n  d.htDiscord = (d.hb!=null && d.ht!=null && Math.abs(d.ht - 3*d.hb) > 4.5);\n  d.implausivel = [];\n  if(d.hb!=null && (d.hb<=0 || d.hb>25)) d.implausivel.push('hemoglobina');\n  if(d.ferritina!=null && (d.ferritina<0 || d.ferritina>20000)) d.implausivel.push('ferritina');\n  if(d.ist!=null && (d.ist<0 || d.ist>100)) d.implausivel.push('saturação da transferrina');\n  if(d.peso!=null && (d.peso<=0 || d.peso>350)) d.implausivel.push('peso');\n  if(d.vcm!=null && (d.vcm<40 || d.vcm>150)) d.implausivel.push('VCM');\n\n  /* --- estado do ferro --- */\n  let st = 'indef', label='Dados insuficientes', desc='', cid='';\n  const F = d.ferritina, I = d.ist;\n  const ferroBaixo = (F!=null && F<30) || (I!=null && I<20) || d.retheBaixo;\n\n  if(F!=null || I!=null){\n    if(F!=null && F<30){\n      st = 'absoluta';\n    } else if(F!=null && F>=30 && F<100 && d.inflam && I!=null && I<20){\n      st = 'mista';\n    } else if(F!=null && F>=100 && I!=null && I<20 && d.inflam){\n      st = 'adc';\n    } else if(I!=null && I<20 && (F==null || F<100)){\n      st = 'absoluta';\n    } else if((F!=null && F>=30) && (I==null || I>=20)){\n      st = 'sem';\n    }\n    if(st==='sem' && d.retheBaixo) st = 'funcional';\n  }\n\n  /* --- estadiamento (Quadro 2 do PCDT) --- */\n  let estagio = 0;\n  if(st==='absoluta' || st==='mista' || st==='funcional'){\n    if(d.anemia===true) estagio = 3;\n    else if((I!=null && I<20) || d.retheBaixo || d.micro || d.anisoc) estagio = 2;\n    else estagio = 1;\n  }\n  d.estagio = estagio;\n\n  if(st==='absoluta' && estagio===3){ label='Anemia por deficiência de ferro'; cid='D50.0 / D50.8'; desc='Deficiência absoluta de ferro com repercussão eritropoiética. Reposição terapêutica plena mais investigação etiológica obrigatória.'; }\n  else if(st==='absoluta' && estagio===2){ label='Eritropoiese deficiente em ferro'; cid='E61.1'; desc='Estoques esgotados e oferta de ferro à medula já reduzida, mas hemoglobina ainda preservada. Tratar agora evita a anemia.'; }\n  else if(st==='absoluta' && estagio===1){ label='Depleção dos estoques de ferro'; cid='E61.1'; desc='Ferritina baixa com eritropoiese ainda suficiente. Reposição indicada; pelo PCDT, apenas com sulfato ferroso.'; }\n  else if(st==='mista'){ label='Deficiência de ferro associada a doença crônica'; cid='D50.8 + CID da doença de base'; desc='Ferritina entre 30 e 100 ng/mL com IST < 20% em contexto inflamatório: há componente absoluto sobreposto ao bloqueio de hepcidina. Repor ferro e tratar a doença de base.'; }\n  else if(st==='funcional'){ label='Deficiência funcional de ferro'; cid='D63.8 / E61.1'; desc='Estoques aparentemente adequados, mas oferta de ferro ao eritroblasto insuficiente (Ret-He/CHr reduzido). Reavaliar em conjunto com a doença de base.'; }\n  else if(st==='adc'){ label='Anemia de doença crônica predominante'; cid='D63.8'; desc='Ferritina ≥ 100 ng/mL com IST baixo e inflamação: o padrão é de sequestro de ferro, não de carência. Ferro isolado tende a não corrigir — tratar a doença de base.'; }\n  else if(st==='sem' && d.anemia===true){ label='Anemia sem deficiência de ferro'; cid='D64.9 (a esclarecer)'; desc='Reserva de ferro preservada. Reposição de ferro não está indicada; prosseguir na investigação etiológica da anemia.'; }\n  else if(st==='sem'){ label='Sem deficiência de ferro'; cid='—'; desc='Reserva e oferta de ferro preservadas. Não há indicação de reposição.'; }\n  else if(st==='indef'){ label='Estadiamento incompleto'; cid='—'; desc='Falta ferritina ou índice de saturação da transferrina. Sem pelo menos um desses dois, não é possível afirmar nem excluir deficiência de ferro — a morfologia isolada não decide.'; }\n\n  d.st = st; d.label = label; d.cid = cid; d.desc = desc;\n  d.repor = ['absoluta','mista','funcional'].includes(st);\n\n  /* --- índices discriminantes --- */\n  d.mentzer = (d.vcm!=null && d.rbc!=null && d.rbc>0) ? d.vcm/d.rbc : null;\n  d.greenking = (d.vcm!=null && d.rdw!=null && d.hb!=null && d.hb>0) ? (Math.pow(d.vcm,2)*d.rdw)/(d.hb*100) : null;\n  const idxTal = (d.mentzer!=null && d.mentzer<13) || (d.greenking!=null && d.greenking<65);\n  d.suspTal = idxTal && !(d.ferritina!=null && d.ferritina<30 && d.rdw!=null && d.rdw>16);\n\n  /* --- via --- */\n  const inds = [...document.querySelectorAll('.iv-ind:checked')].map(e=>e.dataset.txt);\n  const cis  = [...document.querySelectorAll('.iv-ci:checked')].map(e=>e.dataset.txt);\n  if(I!=null && I>45) cis.push('índice de saturação da transferrina acima de 45%');\n  if(F!=null && F>=500) cis.push('ferritina ≥ 500 ng/mL');\n  if(d.gest && d.ig!=null && d.ig<12) cis.push('gestação com menos de 12 semanas');\n  if(d.gest && d.ig!=null && d.ig>=12 && d.ig<14) cis.push('gestação no limiar de 12–14 semanas — preferir aguardar o 2º trimestre');\n  d.ivInd = inds; d.ivCI = cis;\n  d.via = inds.length>0 && cis.length===0 ? 'IV' : 'VO';\n  if(inds.length>0 && cis.length>0) d.via = 'BLOQ';\n  d.drc = on('i_drc');\n\n  /* --- Ganzoni --- */\n  let hbAlvo = num('hbalvo');\n  if(hbAlvo==null){\n    if(d.pesoUso!=null && d.pesoUso<35) hbAlvo = 13;\n    else if(d.gest) hbAlvo = 13;\n    else if(d.sexo==='M') hbAlvo = 15;\n    else hbAlvo = 14;\n  }\n  d.hbAlvo = hbAlvo;\n  if(d.pesoUso!=null && d.hb!=null){\n    const dep = d.pesoUso<35 ? 15*d.pesoUso : 500;\n    d.deposito = dep;\n    d.deficitHb = Math.max(0, d.pesoUso*(hbAlvo-d.hb)*2.4);\n    d.ganzoni = d.deficitHb + dep;\n  } else d.ganzoni = null;\n\n  d.regime = document.querySelector('input[name=reg]:checked').value;\n  return d;\n}\n\n/* ---------- prescrição oral ---------- */\nfunction oral(d){\n  const L = [];\n  const cp = 40, sol = 25, xar = 5;\n  let alvo, faixa, dur, obs=[];\n\n  if(d.crianca){\n    if(d.peso==null){\n      return {linhas:['Informe o peso para calcular a dose pediátrica em mg/kg.'], obs:[], dur:'—', faixa:d.estagio===3?'3 a 6 mg/kg/dia':'2,5 a 5 mg/kg/dia'};\n    }\n    const mgkg = d.estagio===3 ? 4 : 3;\n    const total = Math.min(120, Math.round((d.peso||0)*mgkg));\n    alvo = total; faixa = d.estagio===3 ? '3 a 6 mg/kg/dia' : '2,5 a 5 mg/kg/dia';\n    dur = d.estagio===3 ? '3 a 6 meses' : '2 a 3 meses';\n    const usaXarope = (d.peso||99) <= 10;\n    const conc = usaXarope ? xar : sol;\n    const nome = usaXarope ? 'Sulfato ferroso xarope 5 mg/mL de ferro elementar (frasco 100 mL)'\n                           : 'Sulfato ferroso solução oral 25 mg/mL de ferro elementar (frasco 30 mL)';\n    const mlDia = total/conc;\n    if(d.regime==='pcdt'){\n      const mlDose = mlDia/3;\n      L.push(nome);\n      L.push(`Tomar ${fmt(mlDose,2)} mL por via oral, três vezes ao dia, nos intervalos das refeições.`);\n      L.push(`Dose diária total: ${total} mg de ferro elementar (${mgkg} mg/kg/dia; ${fmt(mlDia,2)} mL/dia).`);\n    } else if(d.regime==='alternado'){\n      L.push(nome);\n      L.push(`Tomar ${fmt(mlDia,2)} mL por via oral, uma vez ao dia, em dias alternados, 1 hora antes de uma refeição.`);\n      L.push(`Dose por administração: ${total} mg de ferro elementar (${fmt(mlDia,2)} mL).`);\n    } else {\n      L.push(nome);\n      L.push(`Tomar ${fmt(mlDia,2)} mL por via oral, uma vez ao dia, 1 hora antes de uma refeição.`);\n      L.push(`Dose diária: ${total} mg de ferro elementar (${mgkg} mg/kg/dia).`);\n    }\n    if(!usaXarope) obs.push('Solução oral 25 mg/mL: as bulas brasileiras mais comuns trazem 25 gotas por mL, de modo que <b>1 gota equivale a 1 mg de ferro elementar</b> — o que torna a conversão direta por peso. Ainda assim, confirme no rótulo do lote dispensado: há fabricantes com 20 gotas/mL, em que cada gota passa a 1,25 mg.');\n    obs.push('Administrar preferencialmente com suco cítrico; evitar leite, chá, cereais integrais e chocolate no mesmo horário.');\n    obs.push('Pode escurecer as fezes (esperado) e manchar transitoriamente o esmalte dentário — oferecer com canudo e higienizar após.');\n  } else {\n    if(d.estagio===3){\n      if(d.idade!=null && d.idade>=60){ alvo=40; faixa='PCDT: 15 mg/dia em idosos'; }\n      else if(d.sexo==='M'){ alvo=120; faixa='120 mg/dia (homens adultos)'; }\n      else { alvo=120; faixa='100 a 200 mg/dia (mulheres e gestantes)'; }\n      dur = '3 a 6 meses (mínimo 90 dias), até ferritina ≥ 30 ng/mL';\n    } else {\n      alvo = 80; faixa='60 a 100 mg/dia'; dur='2 a 3 meses, até ferritina ≥ 30 ng/mL';\n    }\n    const n = Math.round(alvo/cp);\n    L.push('Sulfato ferroso 40 mg de ferro elementar (equivalente a ~200 mg de sulfato ferroso) — comprimido');\n    if(d.regime==='pcdt'){\n      L.push(n>=3\n        ? `Tomar 1 comprimido por via oral, três vezes ao dia, nos intervalos das refeições.`\n        : `Tomar 1 comprimido por via oral, ${n} vez(es) ao dia, nos intervalos das refeições.`);\n      L.push(`Dose diária total: ${n*cp} mg de ferro elementar.`);\n    } else if(d.regime==='alternado'){\n      L.push(`Tomar ${n} comprimido(s) por via oral, em dose única, em dias alternados (segunda, quarta e sexta-feira), 1 hora antes do café da manhã.`);\n      L.push(`Dose por administração: ${n*cp} mg de ferro elementar.`);\n    } else {\n      L.push(`Tomar ${n} comprimido(s) por via oral, em dose única diária, 1 hora antes do café da manhã.`);\n      L.push(`Dose diária: ${n*cp} mg de ferro elementar.`);\n    }\n    L.push(`Quantidade para 30 dias: ${d.regime==='alternado' ? Math.ceil(n*13) : n*30} comprimidos.`);\n    if(n>1) obs.push('Contradição interna do PCDT a registrar: a tabela de posologia autoriza 100 a 200 mg/dia em mulheres e 120 mg/dia em homens, mas o texto corrido sugere evitar doses diárias superiores a 40 mg de ferro elementar, alegando barreira da mucosa intestinal. A dose acima segue a tabela de posologia, que é a seção normativa; se optar pelo teto de 40 mg, registre a escolha.');\n    obs.push('Tomar com o estômago vazio (1 hora antes ou 2 horas após as refeições) ou ao deitar; associar suco cítrico aumenta a absorção.');\n    obs.push('Não tomar junto de leite, café, chá, antiácidos, cálcio, levotiroxina, quinolonas ou tetraciclinas — espaçar em pelo menos 2 horas.');\n    obs.push('Escurecimento das fezes é esperado e não indica sangramento.');\n    if(d.gest) obs.push('Associar ácido fólico 5 mg (ou 400 µg) por via oral, uma vez ao dia, conforme protocolo do pré-natal.');\n    if(d.idade!=null && d.idade>=60) obs.push('O PCDT preconiza 15 mg/dia em idosos (Rimon 2005): equivale a 0,6 mL da solução oral 25 mg/mL. A dose de 40 mg/dia acima é a menor apresentação sólida disponível — escolher conforme tolerância.');\n  }\n\n  if(d.regime==='alternado') obs.unshift('Regime em dias alternados: previsto no próprio PCDT como conduta de monitoramento para manter o tratamento e melhorar a adesão (“alternância dos dias de administração”). A base fisiopatológica é que a dose única a cada 48 h evita o pico de hepcidina induzido pela dose anterior, aumentando a absorção fracionada (Stoffel, Lancet Haematol 2017; Haematologica 2020).');\n  if(d.regime==='unica') obs.unshift('Dose única diária: a fração absorvida cai quando a dose é fracionada ao longo do dia, pelo aumento agudo da hepcidina (Moretti, Blood 2015). A dose diária total permanece dentro da faixa do PCDT, que só especifica fracionamento em três administrações para crianças.');\n  if(on('o_ibp')) obs.push('Uso contínuo de IBP reduz a absorção do ferro ferroso: reavaliar a real indicação do IBP e priorizar suco cítrico junto à dose.');\n  if(on('o_gastrite')) obs.push('Gastrite atrófica, H. pylori ou doença celíaca respondem por parte relevante da ferropenia refratária — pesquisar e tratar antes de rotular como falha terapêutica.');\n\n  return {linhas:L, obs, dur, faixa};\n}\n\n/* ---------- prescrição EV ---------- */\nfunction fatiar(total, maxUnica){\n  const partes = [];\n  let resto = total;\n  let guarda = 0;\n  while(resto > 0 && guarda++ < 12){\n    const p = Math.min(maxUnica, resto);\n    partes.push(p);\n    resto -= p;\n  }\n  return partes;\n}\nfunction ev(d){\n  const blocos = [];\n  const alvoTotal = d.ganzoni;\n\n  if(on('d_sac')){\n    const ampTotal = alvoTotal!=null ? Math.max(1, Math.round(alvoTotal/100)) : null;\n    const sesCheias = ampTotal!=null ? Math.floor(ampTotal/2) : null;\n    const meia = ampTotal!=null ? ampTotal%2 : 0;\n    const L = [];\n    L.push('SACARATO DE HIDRÓXIDO FÉRRICO 20 mg/mL — ampola 5 mL = 100 mg de ferro elementar');\n    if(d.crianca && d.peso!=null){\n      const dose = Math.min(100, 3*d.peso);\n      L.push(`Dose: 3 mg/kg = ${fmt(dose,0)} mg de ferro (${fmt(dose/20,1)} mL da ampola).`);\n      L.push(`Diluir em 200 mL de cloreto de sódio 0,9% e infundir por via intravenosa em 60 minutos.`);\n    } else {\n      const ampSes = (d.peso!=null && d.peso < 30) ? 1 : 2;\n      const mgSes = ampSes*100;\n      L.push(`Dose por sessão: ${mgSes} mg de ferro = ${ampSes===1?'1 ampola':'2 ampolas'} (${ampSes*5} mL).`);\n      if(ampSes===1) L.push(`Limitado a 1 ampola por sessão porque o peso informado (${fmt(d.peso,1)} kg) faria 200 mg ultrapassarem o teto de 7 mg de ferro/kg em dose única.`);\n      L.push(`Diluir ${ampSes===1?'1 ampola':'2 ampolas'} (${mgSes} mg) em ${ampSes*100} mL de cloreto de sódio 0,9%.`);\n      L.push('Infundir por via intravenosa em 30 a 45 minutos, em ambiente com suporte para reações de hipersensibilidade.');\n      L.push('Intervalo mínimo de 48 horas entre as doses; máximo de 500 mg de ferro por semana.');\n      if(ampTotal){\n        const sesCheias2 = Math.floor(ampTotal/ampSes);\n        const meia2 = ampTotal % ampSes;\n        const porSemana = Math.min(3, Math.max(1, Math.floor(500/mgSes)));\n        const totSes = sesCheias2 + meia2;\n        const semanas = Math.ceil(totSes / porSemana);\n        L.push(`Esquema para o déficit calculado: ${ampTotal} ampolas = ${ampTotal*100} mg de ferro elementar.`);\n        L.push(meia2\n          ? `Distribuição: ${sesCheias2} sessão(ões) de ${mgSes} mg + 1 sessão final de 100 mg (1 ampola diluída em 100 mL de cloreto de sódio 0,9%, em 30 minutos). Total de ${totSes} sessões.`\n          : `Distribuição: ${sesCheias2} sessões de ${mgSes} mg (${ampSes===1?'1 ampola':'2 ampolas'} cada). Total de ${totSes} sessões.`);\n        L.push(`Cronograma respeitando o teto de 500 mg/semana e o intervalo mínimo de 48 horas: ${porSemana} sessões por semana — previsão de ${semanas} semana(s).`);\n      }\n      L.push('Não ultrapassar 200 mg por dose nem 7 mg de ferro/kg em dose única.');\n    }\n    L.push('A dose total é arredondada para ampolas inteiras de 100 mg — o déficit de Ganzoni é uma estimativa, e diferenças de até 100 mg em relação ao valor calculado não têm significado clínico.');\n    L.push('Diluente exclusivo: cloreto de sódio 0,9%. Não diluir em glicose nem misturar com outros fármacos.');\n    L.push('Não é necessária dose-teste prévia.');\n    blocos.push({t:'Opção 1 — Sacarato de hidróxido férrico', s:'Disponível no SUS há mais tempo; exige múltiplas sessões.', L});\n  }\n\n  if(on('d_cmf')){\n    const L = [];\n    L.push('CARBOXIMALTOSE FÉRRICA 50 mg de ferro/mL — frasco-ampola de 2 mL (100 mg), 10 mL (500 mg) ou 20 mL (1.000 mg)');\n    if(d.menor18){\n      L.push('NÃO INDICADA: uso restrito a maiores de 18 anos. Utilizar sacarato de hidróxido férrico.');\n    } else {\n      let dose = null;\n      if(d.hb!=null && d.pesoUso!=null){\n        if(d.hb<10) dose = d.pesoUso<70 ? 1500 : 2000;\n        else dose = d.pesoUso<70 ? 1000 : 1500;\n        if(d.pesoUso<35) dose = Math.min(dose, 500);\n      }\n      const maxUnica = d.pesoUso!=null ? Math.min(1000, Math.floor(20*d.pesoUso/100)*100 || 100) : 1000;\n      if(dose!=null){\n        L.push(`Dose cumulativa (tabela peso × Hb da bula/PCDT): ${dose} mg de ferro elementar.`);\n        L.push(`Limite de dose única: menor valor entre 1.000 mg e 20 mg/kg = ${maxUnica} mg, não repetível na mesma semana.`);\n        fatiar(dose, maxUnica).forEach((s,i)=>{\n          L.push(`${i+1}ª infusão: ${s} mg = ${fmt(s/50,0)} mL — diluir em ${s>500?200:100} mL de cloreto de sódio 0,9% e infundir em, no mínimo, ${s>500?15:6} minutos${i>0?', com intervalo mínimo de 7 dias':''}.`);\n        });\n      } else {\n        L.push('Informe peso e hemoglobina para o cálculo da dose cumulativa.');\n      }\n      L.push('Peso < 35 kg: dose cumulativa máxima de 500 mg.');\n      L.push('Alternativa em injeção intravenosa (bolus), com a solução não diluída: até 200 mg de ferro não há tempo de administração estabelecido; de 200 a 500 mg, administrar a 100 mg/minuto; de 500 a 1.000 mg, administrar em 15 minutos.');\n    }\n    L.push('Diluente exclusivo: cloreto de sódio 0,9%; concentração final não inferior a 2 mg de ferro/mL. Não é necessária dose-teste.');\n    L.push('Dosar fósforo sérico antes e 2 a 4 semanas após a infusão — hipofosfatemia é significativamente mais frequente com carboximaltose do que com derisomaltose.');\n    blocos.push({t:'Opção 2 — Carboximaltose férrica', s:'Corrige o déficit em uma ou duas infusões; incorporada pela Portaria SECTICS/MS nº 20/2023.', L});\n  }\n\n  if(on('d_deri')){\n    const L = [];\n    L.push('DERISOMALTOSE FÉRRICA 100 mg de ferro/mL — frasco-ampola de 5 mL (500 mg) ou 10 mL (1.000 mg)');\n    if(d.menor18){\n      L.push('NÃO INDICADA: uso restrito a maiores de 18 anos. Utilizar sacarato de hidróxido férrico.');\n    } else {\n      let dose = null;\n      if(d.hb!=null && d.pesoUso!=null){\n        if(d.hb<10) dose = d.pesoUso<50 ? 500 : (d.pesoUso<70 ? 1500 : 2000);\n        else dose = d.pesoUso<50 ? 500 : (d.pesoUso<70 ? 1000 : 1500);\n        if(d.pesoUso<35) dose = Math.min(dose, 500);\n      }\n      const pesoDose = (d.imc!=null && d.imc>25 && d.pesoIdeal!=null) ? d.pesoIdeal : d.pesoUso;\n      const maxUnica = pesoDose!=null ? Math.min(1000, Math.floor(20*pesoDose/100)*100 || 100) : 1000;\n      if(dose!=null){\n        L.push(`Dose cumulativa: ${dose} mg de ferro elementar.`);\n        L.push(`Limite de dose única: 20 mg/kg = ${maxUnica} mg${(d.imc!=null&&d.imc>25)?' (calculado sobre o peso ideal, porque o IMC é maior que 25)':''}.`);\n        fatiar(dose, maxUnica).forEach((s,i)=>{\n          L.push(`${i+1}ª administração: ${s} mg = ${fmt(s/100,0)} mL — diluir em 100 mL de cloreto de sódio 0,9% e infundir em, no mínimo, ${s>1000?30:15} minutos${i>0?', com intervalo mínimo de 1 semana':''}.`);\n        });\n        L.push('Alternativa em bolus: até 500 mg, três vezes por semana, a até 250 mg de ferro/minuto, não diluído ou em até 20 mL de cloreto de sódio 0,9%.');\n      } else {\n        L.push('Informe peso e hemoglobina para o cálculo da dose cumulativa.');\n      }\n    }\n    L.push('Diluente exclusivo: cloreto de sódio 0,9%; não diluir abaixo de 1 mg de ferro/mL.');\n    blocos.push({t:'Opção 3 — Derisomaltose férrica', s:'Maior dose em administração única; incorporada pela Portaria SECTICS/MS nº 49/2024.', L});\n  }\n\n  if(blocos.length===0) blocos.push({t:'Nenhuma apresentação endovenosa marcada', s:'', L:['Selecione em “Disponibilidade local de ferro EV” o que existe na rede para gerar a prescrição.']});\n  return blocos;\n}\n\n/* ---------- render ---------- */\nfunction render(){\n  const d = compute();\n  const o = $('out');\n\n  if(d.hb==null && d.ferritina==null && d.ist==null){\n    o.innerHTML = `<div class=\"empty\"><b>Aguardando os exames</b>Informe pelo menos hemoglobina e ferritina (ou índice de saturação da transferrina) para o estadiamento e a prescrição.</div>`;\n    return;\n  }\n\n  let h = '';\n\n  h += `<div class=\"verdict\"><p class=\"vlab\">Conclusão diagnóstica</p><h2>${esc(d.label)}</h2><p>${esc(d.desc)}</p>${d.cid&&d.cid!=='—'?`<span class=\"cid\">CID-10 · ${esc(d.cid)}</span>`:''}</div>`;\n\n  /* régua */\n  const segs = [\n    ['Estoques normais','Ferritina ≥ 30 · IST ≥ 20% · Hb normal'],\n    ['1 · Depleção dos estoques','Ferritina &lt; 30 · IST normal · Hb normal'],\n    ['2 · Eritropoiese deficiente','IST &lt; 20% · VCM/HCM ↓ · RDW ↑ · Hb normal'],\n    ['3 · Anemia ferropriva','Hb abaixo do corte para idade e sexo']\n  ];\n  let pos = d.st==='sem' ? 0 : d.estagio;\n  if(!d.repor && d.st!=='sem') pos = -1;\n  h += `<div class=\"ruler\"><h3>Régua de estadiamento férrico — Quadro 2 do PCDT</h3><div class=\"track\">`;\n  segs.forEach((s,i)=>{ h += `<div class=\"seg ${i<=pos&&pos>0?'on':''} ${i===pos?'here':''}\"><div class=\"segbar\"></div></div>`; });\n  h += `</div><div class=\"track\" style=\"gap:3px\">`;\n  segs.forEach((s,i)=>{ h += `<div class=\"seg ${i===pos?'here':''}\"><div class=\"segtxt\"><b>${s[0]}</b><br>${s[1]}</div></div>`; });\n  h += `</div><p class=\"rulernote\">Corte de hemoglobina aplicado: <b>${fmt(d.corte.v,1)} g/dL</b> (${d.corte.txt}).${d.hb!=null?` Hb informada: ${fmt(d.hb,1)} g/dL.`:''}</p></div>`;\n\n  /* tabela de índices */\n  h += `<div class=\"card\"><h3>Índices derivados</h3><div class=\"inner\"><table><thead><tr><th>Parâmetro</th><th>Valor</th><th>Leitura</th></tr></thead><tbody>`;\n  const row=(a,b,c)=>`<tr><td>${a}</td><td class=\"num\">${b}</td><td>${c}</td></tr>`;\n  if(d.ist!=null) h += row('Saturação da transferrina'+(d.istCalc?' (calculada)':''), fmt(d.ist,1)+' %', d.ist<20?'<span class=\"tagbad\">Reduzida — oferta de ferro insuficiente</span>':(d.ist>45?'<span class=\"tagbad\">Elevada — contraindica ferro EV</span>':'<span class=\"tagok\">Dentro da faixa</span>'));\n  if(d.ferritina!=null) h += row('Ferritina', fmt(d.ferritina,0)+' ng/mL', d.ferritina<30?'<span class=\"tagbad\">Estoques esgotados</span>':(d.ferritina<100?(d.inflam?'<span class=\"tagmid\">Zona cinzenta em inflamação</span>':'<span class=\"tagok\">Estoques presentes, ainda baixos</span>'):'<span class=\"tagok\">Estoques adequados ou reagente de fase aguda</span>'));\n  if(d.rethe!=null) h += row('Ret-He / CHr', fmt(d.rethe,1)+' pg', d.rethe<29?'<span class=\"tagbad\">Hemoglobinização reticulocitária reduzida</span>':'<span class=\"tagok\">Adequada</span>');\n  if(d.mentzer!=null) h += row('Índice de Mentzer (VCM/hemácias)', fmt(d.mentzer,1), d.mentzer<13?'<span class=\"tagmid\">Sugere traço talassêmico</span>':'<span class=\"tagok\">Compatível com ferropenia</span>');\n  if(d.greenking!=null) h += row('Índice de Green &amp; King', fmt(d.greenking,1), d.greenking<65?'<span class=\"tagmid\">Sugere traço talassêmico</span>':'<span class=\"tagok\">Compatível com ferropenia</span>');\n  if(d.retic!=null) h += row('Reticulócitos', fmt(d.retic,2)+' %', d.retic<1?'<span class=\"tagmid\">Resposta hipoproliferativa — compatível com carência não tratada</span>':(d.retic>3?'<span class=\"tagok\">Reticulocitose — resposta ao tratamento ou hemólise</span>':'Dentro da faixa'));\n  if(d.plaq!=null) h += row('Plaquetas', fmt(d.plaq,0)+' mil/µL', d.plaq>450?'<span class=\"tagmid\">Trombocitose reativa, achado frequente na ferropenia e no sangramento crônico</span>':(d.plaq<150?'<span class=\"tagbad\">Plaquetopenia — não é da ferropenia, investigar</span>':'<span class=\"tagok\">Normal</span>'));\n  if(d.htDiscord) h += row('Coerência Hb × Ht', fmt(d.hb,1)+' × '+fmt(d.ht,1), '<span class=\"tagmid\">Ht difere de ~3× a Hb — conferir a digitação ou a amostra</span>');\n  if(d.imc!=null) h += row('IMC', fmt(d.imc,1)+' kg/m²', d.pesoIdeal!=null?`Peso ideal (IMC 25): ${fmt(d.pesoIdeal,1)} kg`:'—');\n  h += `</tbody></table>${d.ist==null?'<p style=\"font-size:12.5px;color:var(--slate)\">Informe ferro sérico e CTLF (ou o IST direto) — sem a saturação da transferrina não é possível separar deficiência absoluta de bloqueio inflamatório.</p>':''}</div></div>`;\n\n  /* alertas */\n  let flags = '';\n  if(d.implausivel.length) flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Valor fora da faixa plausível</b>Confira a digitação de: ${esc(d.implausivel.join(', '))}. O cálculo segue, mas o resultado não é confiável.</div></div>`;\n  if(d.idade==null) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Idade não informada</b>Aplicando o corte de hemoglobina de mulher adulta (12 g/dL) como padrão. Em homens e idosos o corte muda, e a dose oral também — preencha a idade.</div></div>`;\n  if(d.peso==null) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Peso não informado</b>Sem peso não há fórmula de Ganzoni, dose pediátrica em mg/kg nem tabela de dose cumulativa dos ferros endovenosos.</div></div>`;\n  if(d.drc) flags += `<div class=\"flag stop\"><span class=\"ic\">→</span><div><b>Doença renal crônica marcada</b>Conduza pelo PCDT de Anemia na Doença Renal Crônica, que tem critérios próprios de alvo de ferritina, IST e uso de agentes estimuladores da eritropoiese. Este cálculo não se aplica.</div></div>`;\n  if(d.suspTal) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Padrão sugestivo de traço talassêmico</b>Microcitose desproporcional ao grau de anemia com RDW pouco alterado. Solicite eletroforese de hemoglobina — mas só depois de corrigir a ferropenia, porque a deficiência de ferro reduz falsamente a HbA2.</div></div>`;\n  if(d.st==='adc') flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Ferro isoladamente não deve corrigir este quadro</b>O padrão é de sequestro de ferro por hepcidina. Priorize o diagnóstico e o tratamento da condição inflamatória, infecciosa ou neoplásica de base.</div></div>`;\n  if(d.st==='sem' && d.anemia===true) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Anemia com ferro normal</b>Investigar B12, folato, função renal e tireoidiana, hemólise (LDH, bilirrubina indireta, haptoglobina, reticulócitos) e causas medulares antes de qualquer reposição.</div></div>`;\n  if(d.hb!=null && d.hb<7) flags += `<div class=\"flag stop\"><span class=\"ic\">!</span><div><b>Hemoglobina abaixo de 7 g/dL</b>Avaliar transfusão de concentrado de hemácias, sobretudo se houver sintomas isquêmicos, instabilidade hemodinâmica ou sangramento ativo. Encaminhar para pronto atendimento e repor ferro depois da estabilização.</div></div>`;\n  if(d.ivInd.length>0 && d.ivCI.length>0) flags += `<div class=\"flag stop\"><span class=\"ic\">✕</span><div><b>Indicação e contraindicação de ferro EV coexistem</b>Contraindicações registradas: ${esc(d.ivCI.join('; '))}. Resolver a contraindicação (tratar a infecção, aguardar o 2º trimestre, revisar sobrecarga) antes de infundir; enquanto isso, considerar suporte transfusional se houver descompensação.</div></div>`;\n  if(d.lact && d.via==='IV') flags += `<div class=\"flag info\"><span class=\"ic\">i</span><div><b>Lactação</b>O PCDT e as bulas nacionais listam a amamentação como restrição ao ferro EV, mas a transferência do ferro parenteral para o leite é desprezível e as diretrizes internacionais consideram o uso compatível. Registre a decisão compartilhada no prontuário.</div></div>`;\n  if(on('i_rapido')) flags += `<div class=\"flag warn\"><span class=\"ic\">!</span><div><b>Ressalva do PCDT sobre correção rápida</b>O ferro endovenoso antes do parto ou no pré-operatório não corrige a anemia em tempo hábil para o procedimento, porque a formação de novas hemácias leva de sete a dez dias. Programe a infusão com antecedência ou avalie suporte transfusional se o procedimento for iminente.</div></div>`;\n  if(d.gest && d.via==='IV') flags += `<div class=\"flag info\"><span class=\"ic\">i</span><div><b>Critério do PCDT para gestante</b>O ferro endovenoso é indicado a partir do 2º trimestre em anemia moderada a grave (Hb abaixo de 9 g/dL) com necessidade de correção rápida, risco aumentado de hemorragia, intolerância materna relevante ou anemia por outras comorbidades. Também pode ser considerado no fim da gestação, quando não há mais tempo para o ferro oral e ainda se pode evitar transfusão no período antenatal.${d.hb!=null&&d.hb>=9?' <b>A Hb informada está em 9 g/dL ou acima</b> — justifique no relatório qual das demais condições se aplica.':''}</div></div>`;\n  if(flags) h += flags;\n\n  /* prescrição */\n  if(d.st==='indef'){\n    h += `<div class=\"card\"><h3>Faltam dados para decidir</h3><div class=\"inner\"><p>Informe a <b>ferritina</b> e, se possível, <b>ferro sérico com CTLF</b> (ou o IST direto). Sem esses parâmetros a calculadora não gera prescrição: microcitose e RDW elevado sozinhos não distinguem ferropenia de talassemia nem de anemia de doença crônica.</p></div></div>`;\n  } else if(!d.repor){\n    h += `<div class=\"card\"><h3>Sem indicação de reposição de ferro</h3><div class=\"inner\"><p>Os parâmetros informados não caracterizam deficiência de ferro. Reposição empírica de ferro em quem não é ferropênico não traz benefício e adiciona risco de sobrecarga, já que não existe via fisiológica de excreção.</p></div></div>`;\n  } else if(d.via==='BLOQ'){\n    const oralTb = on('i_intol') || on('i_ci');\n    h += `<div class=\"card route\"><h3>Ferro endovenoso suspenso</h3><div class=\"inner\">`;\n    h += `<p><b>Indicação presente:</b> ${esc(d.ivInd.join('; '))}.</p>`;\n    h += `<p><b>Contraindicação que suspende a infusão:</b> ${esc(d.ivCI.join('; '))}.</p>`;\n    h += `<p>Resolva primeiro a contraindicação — tratar a infecção aguda, aguardar a 12ª semana de gestação, reavaliar sobrecarga quando IST > 45% ou ferritina ≥ 500 — e recalcule. Reagende a infusão e registre a pendência no prontuário para não se perder no seguimento.</p>`;\n    if(oralTb){\n      h += `<p>Como a via oral também está comprometida neste caso, o intervalo até liberar a infusão deve ser coberto por vigilância clínica: se houver descompensação hemodinâmica, sintomas isquêmicos ou queda progressiva da Hb, o suporte transfusional passa a ser a conduta.</p>`;\n    } else {\n      const p = oral(d);\n      h += `<p>Enquanto isso, mantenha a via oral, que não está contraindicada aqui:</p>`;\n      h += `<pre class=\"rx\">${p.linhas.map(esc).join('\\n')}\\n\\nDuração: ${esc(p.dur)}.</pre>`;\n    }\n    h += `<button class=\"btn\" type=\"button\" onclick=\"copiar()\">Copiar prescrição</button></div></div>`;\n  } else if(d.via==='IV'){\n    h += `<div class=\"card route\"><h3>Via endovenosa</h3><div class=\"inner\">`;\n    h += `<p><b>Critério que definiu a via:</b> ${esc(d.ivInd.join('; '))}.</p>`;\n    if(d.ganzoni!=null){\n      h += `<p><b>Déficit total de ferro (fórmula de Ganzoni):</b> ${fmt(d.ganzoni,0)} mg</p>`;\n      h += `<pre class=\"rx\">Ferro (mg) = peso (kg) × (Hb alvo − Hb atual) × 2,4 + ferro de depósito\n           = ${fmt(d.pesoUso,1)} × (${fmt(d.hbAlvo,1)} − ${fmt(d.hb,1)}) × 2,4 + ${fmt(d.deposito,0)}\n           = ${fmt(d.ganzoni,0)} mg de ferro elementar</pre>`;\n      if(d.gest) h += `<p style=\"font-size:12.5px;color:var(--slate);margin-top:8px\">Peso utilizado: ${d.pesopre!=null?'pré-gestacional':'atual (informe o peso pré-gestacional para maior precisão)'}.</p>`;\n    } else {\n      h += `<p>Informe peso e hemoglobina para calcular o déficit pela fórmula de Ganzoni.</p>`;\n    }\n    h += `<p style=\"font-size:12.5px;color:var(--slate);margin-top:10px\">O déficit de Ganzoni orienta o sacarato de hidróxido férrico, que é dosado por sessão. Carboximaltose e derisomaltose não usam Ganzoni: têm tabela fixa de peso × Hb na bula, que costuma resultar em dose maior. Divergência entre os dois números é esperada e não é erro.</p>`;\n    ev(d).forEach(b=>{\n      h += `<div style=\"margin-top:16px\"><p style=\"font-family:Fraunces,serif;font-weight:600;font-size:15px;margin-bottom:2px\">${esc(b.t)}</p>${b.s?`<p style=\"font-size:12.5px;color:var(--slate)\">${esc(b.s)}</p>`:''}<pre class=\"rx\">${b.L.map(esc).join('\\n')}</pre></div>`;\n    });\n    h += `<p style=\"margin-top:14px\"><b>Antes de cada infusão:</b> confirmar ausência de infecção aguda, checar IST e ferritina, garantir carrinho de emergência, adrenalina e monitorização, e observar o paciente por 30 minutos após o término.</p>`;\n    h += `<button class=\"btn\" type=\"button\" onclick=\"copiar()\">Copiar prescrição</button></div></div>`;\n  } else {\n    const p = oral(d);\n    h += `<div class=\"card route oral\"><h3>Via oral — sulfato ferroso (CBAF, disponível na UBS)</h3><div class=\"inner\">`;\n    h += `<pre class=\"rx\">${p.linhas.map(esc).join('\\n')}\\n\\nDuração: ${esc(p.dur)}.</pre>`;\n    h += `<p style=\"margin-top:12px\"><b>Faixa preconizada pelo PCDT:</b> ${esc(p.faixa)}.</p>`;\n    h += `<p><b>Orientações que devem constar da receita ou do registro:</b></p><ul>${p.obs.map(x=>`<li>${x}</li>`).join('')}</ul>`;\n    if(d.ivInd.length===0 && (on('o_intolprev'))){\n      let fp = [];\n      fp.push('FERRIPOLIMALTOSE (complexo férrico polimaltosado) — comprimido 100 mg de ferro elementar; solução oral 50 mg/mL; xarope 10 mg/mL');\n      if(d.gest) fp.push('Gestantes: 1 comprimido (100 mg de ferro elementar) por via oral, 2 a 3 vezes ao dia, até a normalização da Hb — ou 20 a 30 mL de xarope ao dia. Em seguida, 1 comprimido ao dia pelo menos até o fim da gravidez, para restaurar as reservas.');\n      else if(d.idade!=null && d.idade<1) fp.push('Bebês até 1 ano: 2 gotas/kg/dia por via oral, por 3 a 5 meses, até a normalização da Hb.');\n      else if(d.crianca) fp.push('Crianças menores de 12 anos (até 35 kg): 20 gotas por via oral, 1 a 2 vezes ao dia, ou 5 a 10 mL de xarope ao dia, até a normalização da Hb.');\n      else fp.push('Adultos: 1 comprimido (100 mg de ferro elementar) por via oral, 1 a 3 vezes ao dia, até a normalização da Hb. Em seguida, 1 comprimido ao dia por 2 a 3 meses, para restaurar as reservas.');\n      fp.push('Administrar preferencialmente próximo às refeições — o sal férrico já vem quelado e não interage com os alimentos, dispensando as restrições exigidas pelo sulfato ferroso.');\n      h += `<div class=\"flag info\" style=\"margin-top:8px\"><span class=\"ic\">i</span><div><b>Alternativa formal por intolerância ao sulfato ferroso</b>A ferripolimaltose foi incorporada exatamente para esta indicação (Portaria SECTICS/MS nº 17/2023). Eficácia similar à do sal ferroso, com melhor adesão e menos eventos adversos (10% a 15%). Antes de migrar, o PCDT sugere tentar reduzir a dose, adequar a posologia, administrar junto à refeição ou alternar os dias.</div></div>`;\n      h += `<pre class=\"rx\">${fp.map(esc).join('\\n')}</pre>`;\n    }\n    h += `<button class=\"btn\" type=\"button\" onclick=\"copiar()\">Copiar prescrição</button></div></div>`;\n  }\n\n  /* monitoramento */\n  if(d.repor){\n    h += `<div class=\"card\"><h3>Monitoramento</h3><div class=\"inner\"><table><thead><tr><th>Momento</th><th>O que avaliar</th><th>Resposta esperada</th></tr></thead><tbody>`;\n    if(d.via!=='IV'){\n      h += row('Primeira semana','Fadiga, irritabilidade, tolerância ao esforço, alotriofagia e pernas inquietas','Melhora ou desaparecimento dos sintomas e aparecimento de sensação de bem-estar');\n      h += row('3 a 5 dias','Reticulócitos','Reticulocitose surge entre o 3º e o 5º dia e é máxima entre o 8º e o 10º dia');\n      h += row('3 a 4 semanas','Hemoglobina','Aumento de pelo menos 2 g/dL');\n      h += row('45 a 60 dias','Queda de cabelo e papilas linguais','Melhora da queda de cabelo; reconstituição das papilas ao longo de semanas a meses');\n      h += row('1 a 2 meses','Hemoglobina','Fase 1 do PCDT: normalização da Hb');\n      h += row('8 semanas','Resposta em anemia grave','Ausência de resposta após 8 semanas caracteriza refratariedade e abre indicação de ferro endovenoso');\n      h += row('Após a Hb normalizar, a cada 2–3 meses','Ferritina','Fase 2: reposição dos estoques em 2 a 6 meses. A normalização da ferritina sinaliza a suspensão do tratamento <span class=\"tagmid\">alvo ≥ 30 ng/mL</span>');\n      h += row('2 a 3 meses','Tolerância e adesão','Se houver intolerância: reduzir a dose, adequar a posologia, administrar junto à refeição ou alternar os dias de administração — condutas previstas no próprio PCDT para manter o tratamento');\n    } else {\n      h += row('4 semanas','Hemoglobina','Não reavaliar antes disso: é o tempo necessário para eritropoiese e utilização do ferro. Se ainda houver necessidade, recalcular a dose');\n      h += row('Antes de cada nova dose','Índice de saturação da transferrina','O PCDT define o IST abaixo de 20% como o exame que confere maior segurança para o uso do ferro endovenoso');\n      h += row('Durante a infusão','Extravasamento venoso','Interromper imediatamente — o extravasamento causa dor, irritação e coloração amarronzada da pele, que pode ser permanente');\n      h += row('Durante a infusão','Hipersensibilidade','Interromper diante de rubor, dispneia, broncoespasmo, hipotensão, dor torácica ou alteração do nível de consciência');\n      h += row('Exposição prolongada ou dose alta','Fósforo sérico','Rastrear hipofosfatemia, sobretudo com deficiência de vitamina D, má absorção de cálcio e fosfato, hiperparatireoidismo secundário, telangiectasia hemorrágica hereditária, doença inflamatória intestinal ou osteoporose');\n      h += row('4 a 8 semanas','Ferritina','<span class=\"tagmid\">Fora do PCDT</span> A ferritina permanece falsamente elevada nas semanas seguintes à infusão; interpretar com cautela');\n    }\n    h += `</tbody></table><p style=\"font-size:12.5px;color:var(--slate)\">Consultas clínicas a cada 3 a 6 meses; verificação de adesão e eventos adversos ao menos semestralmente, independentemente da via. As condutas de monitoramento da deficiência de ferro e da anemia ferropriva são as mesmas; a frequência pode ser individualizada por critério médico.</p>\n    <p style=\"font-size:12.5px;color:var(--slate)\">Se não houver resposta ao ferro oral, o PCDT aponta como causas mais frequentes: persistência da perda de sangue, uso inadequado do medicamento, doença coexistente interferindo, diagnóstico incorreto e deficiências nutricionais combinadas.</p></div></div>`;\n\n    /* investigação */\n    let inv = [];\n    const pos_menop = d.sexo==='F' && d.idade!=null && d.idade>=50;\n    const grupoTGI = (d.sexo==='M' && d.idade!=null && d.idade>50) || pos_menop;\n    if(d.estagio===3){\n      inv.push(`<b>A avaliação do trato gastrointestinal é parte integrante e obrigatória na investigação de qualquer paciente com anemia ferropriva</b> — não apenas dos grupos de maior risco. O PCDT destaca <b>sobretudo homens com mais de 50 anos e mulheres na pós-menopausa</b>${grupoTGI?', faixa em que este paciente se enquadra':''}. Exames iniciais: pesquisa de sangue oculto nas fezes, endoscopia digestiva alta e colonoscopia.`);\n      inv.push('A colonoscopia anormal evidencia doença neoplásica — sobretudo tumor de cólon — em pelo menos 50% dos casos. Tratar a anemia sem investigar a causa pode significar a perda da oportunidade de identificar doença maligna subjacente em fase potencialmente curável.');\n      inv.push('Se endoscopia e colonoscopia forem normais, o PCDT prevê escalada para trânsito de delgado, cintilografia para pesquisa de hemorragia digestiva não ativa, enteroscopia com balão e cápsula endoscópica.');\n    }\n    inv.push('Demandam investigação do TGI: possibilidade de sangramento, dor abdominal, dispepsia, refluxo, perda de peso, sangue oculto positivo, história pessoal ou familiar de doença gastrointestinal ou câncer, ou a simples presença de anemia ferropriva isolada.');\n    if(d.sexo==='F' && !pos_menop) inv.push('Menorragia é a causa isolada mais frequente em mulheres em idade reprodutiva, mas quando a intensidade da anemia é desproporcional à perda menstrual é importante investigar outra fonte: estima-se que 10% a 20% dessas mulheres apresentem sangramento do TGI associado.');\n    inv.push('Pesquisar também sangramento pelo trato respiratório ou urinário, parasitoses, hemólise crônica e história pessoal ou familiar de coagulopatia.');\n    inv.push('Revisar medicamentos e hábitos: ácido acetilsalicílico, anti-inflamatório não esteroidal, anticoagulante, uso contínuo de antiácido ou inibidor de bomba de prótons, uso abusivo de álcool, doação de sangue, gastrectomia ou cirurgia bariátrica prévia (mesmo com suplementação), dieta vegetariana e múltiplas gestações.');\n    inv.push('Parasitológico de fezes: a pesquisa de sangue oculto pode ser falso-negativa em mais da metade dos casos — sensibilidade de 46,7% em população brasileira. O tratamento não deve ser interrompido apenas com base nesse exame.');\n    inv.push('<span class=\"tagmid\">Fora do PCDT</span> Sorologia para doença celíaca (antitransglutaminase IgA com IgA total), pesquisa de <i>H. pylori</i> e de gastrite autoimune — a tríade descrita por Hershko (referência citada pelo próprio Protocolo) na ferropenia refratária ou inexplicada.');\n    if(d.crianca) inv.push('Na criança: alimentação, tempo de aleitamento materno, uso de fórmulas lácteas ou leite integral, profilaxia com ferro, antecedentes perinatais (prematuridade, baixo peso) e deficiência de ferro materna.');\n    h += `<div class=\"card\"><h3>Investigação etiológica</h3><div class=\"inner\"><ul>${inv.map(x=>`<li>${x}</li>`).join('')}</ul></div></div>`;\n\n    /* teste de absorção intestinal — Caso Especial do PCDT */\n    if(on('i_bar') || on('i_refr')){\n      h += `<div class=\"card\"><h3>Teste de absorção intestinal do ferro — executável na UBS</h3><div class=\"inner\"><p>O PCDT prevê este teste como Caso Especial em pacientes submetidos a gastroplastia redutora ou gastrectomia com suspeita de resposta insatisfatória por má absorção. O resultado serve como <b>critério documental para indicar o ferro endovenoso</b>.</p><pre class=\"rx\">1. Dosar ferro sérico com o paciente em jejum.\n2. Administrar sulfato ferroso equivalente a 60 mg de ferro elementar\n   por via oral, com água.\n3. Dosar novamente o ferro sérico após 1 a 2 horas e comparar\n   com o valor em jejum.\n\nInterpretação: aumento superior a 100 sugere absorção intestinal adequada.\nAusência de elevação sugere má absorção e sustenta a via endovenosa.</pre><p style=\"font-size:12.5px;color:var(--slate);margin-top:9px\">O Protocolo expressa esse incremento em ng/mL, unidade que não corresponde à do ferro sérico (µg/dL) — provável inconsistência do documento. Interprete como elevação de cerca de 100 µg/dL sobre o valor de jejum e registre os dois valores brutos no prontuário.</p></div></div>`;\n    }\n\n    /* --- escada de apresentações --- */\n    {\n      const vo = d.via!=='IV';\n      let esc_ = `<div class=\"card\"><h3>Apresentações e alternativas, da mais acessível à menos</h3><div class=\"inner\">`;\n      esc_ += `<table><thead><tr><th>Ordem</th><th>Apresentação e nomes</th><th>Acesso</th><th>Custo</th></tr></thead><tbody>`;\n      if(vo){\n        const n40 = d.crianca ? null : Math.round((d.estagio===3 ? (d.idade!=null&&d.idade>=60?40:120) : 80)/40);\n        const cxMes = n40!=null ? Math.ceil((d.regime==='alternado'? n40*13 : n40*30)/50) : null;\n        esc_ += `<tr><td class=\"num\">1</td><td><b>Sulfato ferroso 40 mg de ferro elementar</b> — comprimido revestido<br><span style=\"color:var(--slate)\">FURP-Sulfato Ferroso, Ferronil e genéricos de Prati-Donaduzzi, Teuto, Natulab, Hipolabor, Belfar</span></td><td>CBAF — farmácia da UBS, sem processo</td><td class=\"tagok\">Gratuito${cxMes?`<br><span style=\"color:var(--slate)\">${cxMes} caixa(s) de 50 cp por mês</span>`:''}</td></tr>`;\n        esc_ += `<tr><td class=\"num\">2</td><td><b>Sulfato ferroso solução oral 25 mg/mL</b> e <b>xarope 5 mg/mL</b> de ferro elementar<br><span style=\"color:var(--slate)\">Apresentações pediátricas do mesmo elenco</span></td><td>CBAF — farmácia da UBS</td><td class=\"tagok\">Gratuito</td></tr>`;\n        esc_ += `<tr><td class=\"num\">3</td><td><b>Sulfato ferroso para gestantes</b><br><span style=\"color:var(--slate)\">Componente de saúde da mulher, junto ao ácido fólico</span></td><td>Farmácia Popular, se a linha estiver ativa no ano corrente — confirme na lista oficial vigente antes de encaminhar</td><td class=\"tagok\">Gratuito</td></tr>`;\n        esc_ += `<tr><td class=\"num\">4</td><td><b>Ferripolimaltose</b> — comprimido mastigável 100 mg, solução oral 50 mg/mL, xarope 10 mg/mL, gotas<br><span style=\"color:var(--slate)\">Noripurum (Takeda) é a referência</span></td><td>Incorporado pela Portaria SECTICS/MS nº 17/2023, mas com oferta pendente — na prática, compra pelo paciente</td><td class=\"tagmid\">Médio — algumas vezes o preço do sulfato ferroso</td></tr>`;\n        esc_ += `<tr><td class=\"num\">5</td><td><b>Ferro quelato bisglicinato</b> e <b>ferro carbonila</b><br><span style=\"color:var(--slate)\">Neutrofer, Neutrofer Fólico, Combiron e similares</span></td><td>Fora da RENAME — compra pelo paciente</td><td class=\"tagmid\">Médio a alto</td></tr>`;\n      } else {\n        esc_ += `<tr><td class=\"num\">1</td><td><b>Sacarato de hidróxido férrico 20 mg/mL</b> — ampola 5 mL<br><span style=\"color:var(--slate)\">Noripurum EV (Takeda) e genéricos</span></td><td>Consta da REMUME de Betim (ampola 5 mL); aplicação em serviço com observação e suporte a reação de hipersensibilidade</td><td class=\"tagok\">Baixo por ampola, mas exige múltiplas sessões</td></tr>`;\n        esc_ += `<tr><td class=\"num\">2</td><td><b>Carboximaltose férrica 50 mg/mL</b> — frascos de 2, 10 e 20 mL<br><span style=\"color:var(--slate)\">Ferinject é a referência</span></td><td>Incorporada pela Portaria SECTICS/MS nº 20/2023; oferta condicionada à publicação do PCDT atualizado</td><td class=\"tagbad\">Alto — ordens de grandeza acima do sacarato</td></tr>`;\n        esc_ += `<tr><td class=\"num\">3</td><td><b>Derisomaltose férrica 100 mg/mL</b> — frascos de 5 e 10 mL<br><span style=\"color:var(--slate)\">Monofer (Pharmacosmos) é a referência</span></td><td>Incorporada pela Portaria SECTICS/MS nº 49/2024; mesma pendência de oferta</td><td class=\"tagbad\">Alto</td></tr>`;\n      }\n      esc_ += `</tbody></table>`;\n      esc_ += `<p style=\"font-size:12.5px;color:var(--slate)\"><b>Atenção à concentração do comprimido comercial.</b> O item do CBAF é de 40 mg de ferro elementar, mas há apresentações de farmácia com <b>60 mg</b> por comprimido. Se o paciente comprar fora da UBS, reconfira o número de comprimidos da receita — a dose é em miligramas de ferro elementar, não em comprimidos.</p>`;\n      esc_ += `<p style=\"font-size:12.5px;color:var(--slate)\">Os custos acima são relativos, não cotações. Para o valor corrente, consulte a tabela CMED da Anvisa (preço máximo ao consumidor e preço máximo de venda ao governo) ou um comparador de farmácias. Preços de ferro endovenoso mudam com frequência e variam entre pregões municipais.</p>`;\n      esc_ += `</div></div>`;\n      h += esc_;\n    }\n\n    /* acesso */\n    let ac = '';\n    if(d.via==='IV'){\n      ac = `<p>O sulfato ferroso é do <b>Componente Básico (CBAF)</b> e sai na própria farmácia da UBS. Já sacarato de hidróxido férrico, carboximaltose férrica e derisomaltose férrica são de <b>uso restrito a serviço hospitalar ou centro de infusão</b> — sem necessidade de internação de 24 horas, mas com estrutura para atendimento de reação anafilática.</p>\n      <p>Encaminhe com o relatório contendo: hemograma, ferritina, IST e PCR datados; a indicação específica de via endovenosa registrada entre os critérios do PCDT; o déficit calculado pela fórmula de Ganzoni; peso e altura; e o Termo de Esclarecimento e Responsabilidade assinado.</p>\n      <p>Ponto de atenção sobre disponibilidade: carboximaltose (Portaria SECTICS/MS nº 20/2023) e derisomaltose (nº 49/2024) foram incorporadas ao SUS, mas o PCDT atualizado que regulamenta a dispensação seguia pendente de publicação — a portaria vigente ainda é a SAS/MS nº 1.247/2014. Na prática, confirme com a Assistência Farmacêutica municipal e com a SES-MG o que está efetivamente disponível antes de prometer a infusão ao paciente.</p>`;\n    } else {\n      ac = `<p>Sulfato ferroso nas três apresentações (comprimido de 40 mg, solução oral de 25 mg/mL e xarope de 5 mg/mL, sempre expressos em ferro elementar) pertence ao <b>Componente Básico da Assistência Farmacêutica</b>, com aquisição municipal — dispensação direta na farmácia da UBS, sem processo.</p>\n      <p>Ferripolimaltose exige documentar intolerância ao sulfato ferroso. Carboximaltose e derisomaltose exigem, além disso, indicação de via endovenosa e são de aplicação em serviço com suporte a reações anafiláticas.</p>`;\n    }\n    h += `<div class=\"card\"><h3>Acesso no SUS</h3><div class=\"inner\">${ac}</div></div>`;\n  }\n\n  o.innerHTML = h;\n}\n\nfunction copiar(){\n  const t = [...document.querySelectorAll('#out .rx')].map(e=>e.innerText).join('\\n\\n');\n  navigator.clipboard.writeText(t).then(()=>{\n    document.querySelectorAll('#out .btn').forEach(b=>{ b.textContent='Prescrição copiada'; setTimeout(()=>b.textContent='Copiar prescrição',2000); });\n  });\n}\n\ndocument.getElementById('f').addEventListener('input', render);\ndocument.getElementById('f').addEventListener('change', render);\nconst _tw=()=>{document.querySelectorAll('#out table').forEach(t=>{\n  if(!t.parentElement.classList.contains('tw')){\n    const w=document.createElement('div'); w.className='tw';\n    t.parentNode.insertBefore(w,t); w.appendChild(t);}});};\nnew MutationObserver(_tw).observe(document.getElementById('out'),{childList:true,subtree:true});\n\nrender();\n<\/script>\n<script>(function(){function _h(){try{parent.postMessage({embId:'ferro_full',embH:document.documentElement.scrollHeight},'*')}catch(e){}}window.addEventListener('load',_h);try{new ResizeObserver(_h).observe(document.body)}catch(e){setInterval(_h,800)}document.addEventListener('input',function(){setTimeout(_h,50)});})();<\/script></body>\n</html>\n";
const embAttr = s => s.replace(/&/g,"&amp;").replace(/"/g,"&quot;");
window.addEventListener("message", e => { const d = e.data; if (d && d.embId && d.embH) document.querySelectorAll(`iframe[data-emb="${d.embId}"]`).forEach(f => { if (f.contentWindow === e.source) f.style.height = (d.embH + 16) + "px"; }); });
Object.assign(CALCS, {
 vitd_full: {nome: "Vitamina D: reposição completa (sua calculadora)", desc: "Sua calculadora de hipovitaminose D (SBPC/ML–SBEM, Endocrine Society 2024, RENAME 2024), integrada ao app. Revisada em 10/10/2026: a REMUME de Betim não lista colecalciferol isolado nem a associação cálcio + D (só carbonato de cálcio 1.250 mg).", html: () => `<iframe class="embcalc" data-emb="vitd_full" title="Vitamina D: reposição completa (sua calculadora)" loading="lazy" allow="clipboard-write" style="width:100%;height:900px;border:1px solid var(--line);border-radius:12px;background:#fff" srcdoc="${embAttr(EMB_HTML.vitd_full)}"></iframe>`, run(){}},
 b12_full: {nome: "Vitamina B12: reposição completa (sua calculadora)", desc: "Sua calculadora de hipovitaminose B12 (NICE NG239 2024, BSH, RENAME 2024), integrada ao app. Revisada em 10/10/2026: o item da RENAME é cianocobalamina 500 mcg/mL (Básico) e não consta da REMUME de Betim.", html: () => `<iframe class="embcalc" data-emb="b12_full" title="Vitamina B12: reposição completa (sua calculadora)" loading="lazy" allow="clipboard-write" style="width:100%;height:900px;border:1px solid var(--line);border-radius:12px;background:#fff" srcdoc="${embAttr(EMB_HTML.b12_full)}"></iframe>`, run(){}},
 ferro_full: {nome: "Ferro: estadiamento e reposição completa (sua calculadora)", desc: "Sua calculadora de reposição de ferro (PCDT 2014 ainda listado pelo MS; CP 98/2024; carboximaltose – Portaria SECTICS 20/2023; derisomaltose – Portaria SECTICS 49/2024), integrada ao app. Revisada em 10/10/2026: o sacarato EV consta da REMUME de Betim.", html: () => `<iframe class="embcalc" data-emb="ferro_full" title="Ferro: estadiamento e reposição completa (sua calculadora)" loading="lazy" allow="clipboard-write" style="width:100%;height:900px;border:1px solid var(--line);border-radius:12px;background:#fff" srcdoc="${embAttr(EMB_HTML.ferro_full)}"></iframe>`, run(){}},
});
CALC_MENU.push(["vitd_full","Vitamina D: reposição completa"],["b12_full","Vitamina B12: reposição completa"],["ferro_full","Ferro: reposição completa"]);
